NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: '[Der] Anfang der frohen Botschaft von Jesus Christus, [dem] Sohn Gottes,',
        2: 'wie es im [Buch] des Propheten Jesaja heißt (geschrieben steht): „Siehe, ich sende meinen Boten vor dir her, der dir den Weg bereiten (alles für dich vorbereiten) wird.“',
        3: '„Stimme eines Rufenden in der Wüste (Wildnis): »Bereitet den Weg des Herrn vor, macht seine Pfade gerade«“,',
        4: 'trat Johannes der Täufer in der Wüste (Wildnis) auf (trat Johannes auf, der in der Wüste taufte) und predigte (verkündete) eine Taufe der Umkehr (Buße; Umkehr-Taufe) zur Vergebung der Sünden.',
        5: 'Und das gesamte judäische Gebiet (Gegend, Land) und alle Jerusalemer begaben sich (gingen) hinaus zu ihm und ließen sich von ihm im Fluss Jordan taufen, wobei (und) sie ihre Sünden bekannten.',
        6: 'Und Johannes pflegte [ein Gewand aus] Kamelhaar und einen Ledergürtel um seine Hüften (Taille) zu tragen und Heuschrecken und wilden Honig zu essen.',
        7: 'Und er predigte (verkündete) {sagend}: „Es kommt nach mir [einer], der mächtiger (stärker) [ist] als ich. Ich bin es nicht wert (gut genug, würdig), mich zu bücken und (gebückt) ihm die Riemen seiner Sandalen aufzubinden!',
        8: "''Ich'' habe euch mit Wasser getauft, ''er'' aber wird euch mit [dem] (im) Heiligem Geist taufen.“",
        9: 'Und {es geschah} in jenen Tagen kam Jesus aus (von) Nazaret [in] Galiläa und ließ sich von Johannes im Jordan taufen.',
        10: 'Und in dem Moment (gleich), als er aus dem Wasser stieg, sah er, wie (dass) der Himmel geteilt (geöffnet) wurde und der Geist wie eine Taube in ihn (zu ihm; auf ihn) herabkam.',
        11: 'Und eine Stimme kam (geschah) aus dem Himmel: „Du bist mein geliebter Sohn, an dir habe ich Freude (Gefallen gefunden)!“',
        12: 'Und gleich danach brachte (führte; trieb) der Geist ihn in die Wüste (Wildnis).',
        13: 'Und er war (lebte, verbrachte) vierzig Tage in der Wüste (Wildnis) und (während, wobei) wurde vom Satan auf die Probe gestellt (versucht), und er war (lebte) unter (mit) den Tieren, und die Engel dienten (versorgten, warteten auf) ihm.',
        14: '{Aber} Nachdem Johannes verhaftet worden war, begab sich (kam) Jesus nach Galiläa und predigte (verkündete) das Evangelium Gottes',
        15: 'und sagte {dass}: „Die Zeit ist eingetreten (gekommen, erfüllt) und Gottes Königsherrschaft (Königreich) ist nahegekommen. Kehrt um (tut Buße) und glaubt an das Evangelium!“',
        16: 'Und während (als) er am Meer von Galiläa entlangging, sah er Simon und Andreas, Simons Bruder, die gerade Wurfnetze (ein Wurfnetz) ins Meer warfen. Sie waren nämlich Fischer.',
        17: 'Und Jesus sagte zu ihnen: „Kommt, [folgt] mir nach, dann werde ich euch [zu] Menschenfischern {werden} machen!“',
        18: 'Und sofort ließen sie [ihre] Netze [liegen] und folgten ihm.',
        19: 'Und nachdem (als) er ein wenig weitergegangen war, sah er Jakobus, den [Sohn] von Zebedäus, und seinen Bruder Johannes. Auch sie [saßen] im Boot [und] brachten [ihre] Netze in Ordnung (setzten instand, besserten aus, flickten),',
        20: 'und er rief sie umgehend (sofort). Und sie ließen ihren Vater mit den bezahlten Arbeitern im Boot zurück und gingen ihm nach.',
        21: 'Und (daraufhin) sie begaben sich nach Kafarnaum {hinein}. {Und} Dann, [am] Sabbat, begann er in der Synagoge (begab er sich in die Synagoge und begann) zu lehren.',
        22: 'Und sie waren tief beeindruckt von seiner Lehre, denn er lehrte sie wie einer, der Vollmacht hat, und nicht wie die Schriftgelehrten.',
        23: 'Und dann (plötzlich) war in der dortigen Synagoge ein Mann mit einem unreinen Geist, und er schrie:',
        24: '{sagend} „Was willst du von uns, Jesus von Nazaret? Bist du gekommen, [um] uns zu vernichten? Ich weiß, wer du bist: der Heilige Gottes!“',
        25: 'Und Jesus wies ihn an (unterwarf ihn seiner Kontrolle) {sagend}: „Sei still (Schweig, Verstumme) und komm (verlass, fahre) aus ihm heraus!“',
        26: 'Und nachdem (während) der unreine Geist ihn geschüttelt und [mit] lauter Stimme geschrien hatte, kam (verließ, fuhr) er aus ihm heraus.',
        27: 'Und alle waren so entgeistert (erstaunt, erschrocken), dass sie einander fragten {wobei sie sagten}: „Was ist das? Eine neue Lehre mit Vollmacht – sogar (selbst, und) den unreinen Geistern befiehlt er, und sie gehorchen ihm!“',
        28: 'Und bald (rasch) verbreitete sich die Kunde von ihm (sein Ruf) überall in der ganzen Umgebung, [in ganz] Galiläa (im ganzen Umland von Galiläa).',
        29: 'Und dann verließen sie {aus} die Synagoge und gingen (begaben sich, kamen) zum (in das) Haus von Simon und Andreas mit Jakobus und Johannes.',
        30: 'Simons Schwiegermutter {aber} lag mit Fieber [im Bett], und sie erzählten (berichteten) ihm gleich von ihr.',
        31: 'Da (Und) ging er zu [ihr] und half ihr beim Aufstehen (richtete sie auf), indem er ihre Hand nahm (ergriff). Da (und) verließ das Fieber sie, und sie begann, sie zu bewirten (bedienen, dienen; bewirtete sie).',
        32: 'Als es Abend geworden (wurde) und die Sonne untergegangen war (unterging), brachte man alle Kranken (denen es schlecht ging) und [alle] Besessenen zu ihm,',
        33: 'und die ganze Stadt war vor der Tür versammelt.',
        34: 'Und er heilte viele Kranke (denen es schlecht ging) von verschiedenen Krankheiten und trieb viele Dämonen aus, aber (und) die Dämonen ließ er nicht sprechen, weil sie ihn kannten.',
        35: 'Und früh morgens, [als es noch] ganz dunkel [war], stand er auf, ging hinaus (verließ [das Haus (die Stadt)]) und ging fort an einen abgeschiedenen Ort, wo er [eine Zeit lang] betete (und betete dort).',
        36: 'Und Simon und [jene], die bei ihm waren, spürten (eilten) ihm nach',
        37: 'und fanden ihn. {und} Sie teilten ihm mit (sagten) {dass}: „Alle fragen (suchen, forschen) nach dir!“',
        38: '{und} Er entgegnete (sagte) ihnen: „Gehen wir stattdessen (lasst uns gehen) anderswohin, in die benachbarten Ortschaften (Dörfer), damit ich auch dort predigen (verkündigen) [kann]. Zu diesem Zweck (Dazu) bin ich nämlich aus [der Stadt] gekommen (bin gekommen, ausgezogen).“',
        39: 'Und er zog (kam; war) durch ganz Galiläa, predigte (verkündigte) in ihren Synagogen und trieb die Dämonen aus.',
        40: 'Und ein Aussätziger (Leprakranker) kam zu ihm, der ihn anflehte und auf die Knie fiel, wobei er ihm zurief (sagte) {dass}: „Wenn du willst, kannst du mich rein machen (heilen)!“',
        41: 'Und [Jesus] hatte Mitleid (wurde zornig), darum streckte er seine Hand aus, berührte [ihn] und sagte zu ihm: „Ich will, sei rein (gereinigt, geheilt)!“',
        42: 'Und sofort verschwand (ging weg) der Aussatz (die Lepra) von ihm, und er wurde rein (gereinigt, geheilt).',
        43: 'Und er ermahnte ihn streng (fuhr ihn an, wies ihn zurecht; bedeutete ihm zu schweigen), schickte ihn ohne Umschweife (sofort) weg (warf ihn hinaus)',
        44: 'und sagte zu ihm: „Sieh, dass du niemandem etwas erzählst (sagst), sondern geh [und] zeige dich dem Priester und dann bringe für deine Reinigung (Heilung) [das Opfer] dar, das Mose vorgeschrieben (festgelegt) hat, als Beweis (Nachweis, Zeugnis, Beleg) [für (gegen)] sie!“',
        45: 'Doch als (nachdem) der [Mann] hinausging, begann er eifrig (überall; viele Dinge) [davon] zu erzählen (predigen, verkündigen) und die Geschichte (Nachricht, das Wort) zu verbreiten, so dass [Jesus] nicht länger in der Lage war, offen (unerkannt, öffentlich, ohne Aufsehen) eine Stadt zu betreten, sondern sich außerhalb in unbewohnten (abgelegenen) Gegenden (Orten) aufhielt (blieb, war). Dennoch (doch, und) kamen [die Leute] weiter (begannen zu kommen) von überall her (aus allen Richtungen) zu ihm.',
    },
    2: {
        1: 'Und als er nach [einigen] Tagen wieder (zurück) nach Kafarnaum kam, wurde bekannt, dass er zuhause (in einem [bestimmten] Haus) war.',
        2: 'Und es kamen (sammelten sich) so viele [Leute] zusammen, dass es keinen Platz mehr gab, auch nicht (nicht einmal) vor (bei) der Tür, und er erläuterte (verkündete, sagte) ihnen [seine] Botschaft (das Wort).',
        3: 'Derweil (Und) kamen [einige Leute] und brachten einen Gelähmten zu ihm. Er wurde von vier [Männern] getragen.',
        4: 'Und (Doch) weil (als) es ihnen wegen die Menschenmenge nicht gelang (sie nicht konnten), ihn zu [Jesus] zu bringen, deckten (entfernten) sie [über der Stelle], wo er war, das Hausdach ab, und ließen die Matte hinab, auf der der Gelähmte lag, nachdem sie eine [entsprechende] Öffnung geschaffen hatten.',
        5: 'Und als Jesus ihren Glauben (Vertrauen) sah, sagte er zu dem Gelähmten: „ [Mein] Sohn (Kind), deine Sünden sind vergeben!“',
        6: 'Es waren {aber} einige Schriftgelehrte (Schreiber) da (dort), die dabeisaßen und [alles miterlebten]. Sie setzten sich (kämpften, überlegten, erwogen) in Gedanken [mit Jesu Worten] auseinander:',
        7: '„Warum redet der so? Er lästert Gott! Wer kann Sünden vergeben außer dem einen Gott (einem – Gott)?“',
        8: 'Und Jesus erkannte in seinem Geist sofort, dass sie so {bei sich} dachten, darum sagte er zu ihnen: „Warum habt ihr solche Gedanken?',
        9: 'Was ist leichter (einfacher) – zu dem Gelähmten zu sagen: »Deine Sünden sind dir vergeben« oder {zu sagen}: »Steh auf und nimm deine Matte und laufe umher«?',
        10: 'Aber damit ihr erkennt (wisst), dass der Menschensohn (Sohn des Menschen; Mensch) [das] Recht (die Macht, Vollmacht, Entscheidungsgewalt) hat, auf der Erde Sünden zu vergeben —“, sagte er zu dem Gelähmten:',
        11: '„— sage ich dir: Steh auf, nimm deine Matte und geh nach Hause!“',
        12: 'Da (und) stand er auf, hob (nahm) umgehend seine Matte auf und ging vor aller Augen hinaus, sodass alle fassungslos (erstaunt, außer sich) waren und Gott lobten. Sie riefen (sagten): „So etwas haben wir noch nie erlebt (gesehen)!“',
        13: 'Danach (Und) ging [Jesus] wieder hinaus, ans (an... entlang) Meer (See). Und die gesamte Menschenmenge kam zu ihm, und er lehrte sie.',
        14: 'Und im Vorbeigehen (als er vorbeiging/vorüberging) sah er Levi, den [Sohn] von Alphäus, an der Zollstelle (Zollhaus, Zoll) sitzen und sagte zu ihm: „Folge mir nach!“Da (Und) stand [Levi] auf und folgte ihm nach.',
        15: 'Und {es ereignete sich} [als] er [später] in seinem Haus bei Tisch war (zu Gast war), nahmen auch (und) viele Zolleinnehmer (Zöllner) und Sünder zusammen mit Jesus und dessen Jüngern an der Mahlzeit teil. Es waren nämlich viele, die ihm nachfolgten.',
        16: 'Doch (Und) als die Schriftgelehrten (Schreiber) der Pharisäer sahen, dass er mit den Sündern und Zolleinnehmern (Zöllnern) aß, sagten sie zu seinen Jüngern: „Warum isst er mit Zolleinnehmern (Zöllnern) und Sündern?“',
        17: 'Aber (Und) als Jesus [das] hörte, sagte er zu ihnen {dass}: „Nicht die Gesunden haben einen Arzt nötig (brauchen), sondern die Kranken (die, denen es schlecht geht). Ich bin nicht gekommen, [um] die Gerechten zu rufen (berufen, zusammenzurufen, einzuladen), sondern die Sünder!“',
        18: 'Nun (Und) hatten die Jünger von Johannes und die Pharisäer die Angewohnheit, regelmäßig zu fasten (fasteten zu dieser Zeit). Und [Leute] kamen und fragten (sagten zu) ihn: „Weshalb fasten die Jünger von Johannes und die Jünger der Pharisäer, aber deine Jünger fasten nicht?“',
        19: 'Da (Und) erwiderte (sagte) Jesus {zu ihnen}: „Ja (etwa) können die Hochzeitsgäste des Bräutigams denn fasten, während der Bräutigam bei ihnen ist? Solange sie den Bräutigam bei sich haben, können sie unmöglich (nicht) fasten!',
        20: 'Es werden jedoch Tage kommen, wenn der Bräutigam {von} ihnen weggenommen wurde, und dann, an diesem Tag, werden sie fasten.',
        21: 'Niemand näht einen Flicken [aus] neuem (ungewalktem, noch nicht eingelaufenem) Stoff auf ein altes Kleidungsstück, sonst reißt das eingesetzte Stück (der Flicken) von ihm ab – das Neue vom Alten – und es entsteht ein [noch] schlimmerer Riss.',
        22: 'Und niemand füllt jungen (neuen) Wein in alte Schläuche. Ansonsten wird der Wein die Schläuche zerreißen (sprengen) und der Wein ist verloren (geht verloren), wie auch die Schläuche. Jungen (neuen) Wein [füllt man] doch (vielmehr) in neue Schläuche.“',
        23: '{Und es ereignete sich} [Einmal, als] er am Sabbat durch die Getreidefelder hindurchging (vorbeiging), da fingen seine Jünger an, unterwegs {die} Ähren abzureißen..',
        24: 'Und die Pharisäer sagten zu ihm: „Schau (siehe), was sie [an] einem Sabbat tun: [etwas], das nicht erlaubt ist! (Warum tun sie [an] einem Sabbat, was nicht erlaubt ist?) “',
        25: 'Aber (und) er erwiderte (sagte) {zu ihnen}: „Habt ihr noch nie gelesen, was David tat, als er in einer Notlage war ([nichts zu essen] hatte) und er und die bei ihm Hunger litten (Hunger hatten)?',
        26: 'Wie er zur Zeit des Hohenpriesters Abjatar in das Haus Gottes ging und die geweihten Brote (Schaubrote, ausgestellten Brote) verzehrte, die außer den Priestern niemand essen darf, und auch denen, die bei ihm waren, [etwas davon] gab?“',
        27: 'Und er fügte hinzu (sagte) {zu ihnen}: „Der Sabbat wurde für (um … willen) den Menschen geschaffen (gemacht) und nicht der Mensch für (um … willen) den Sabbat.',
        28: 'Also (Daher, sodass) ist der Menschensohn (Sohn des Menschen; Mensch) Herr sogar (selbst, auch) [über] den Sabbat.“',
    },
    3: {
        1: 'Und er ging wieder einmal in die Synagoge. Und dort war ein Mann, der eine verkrüppelte (gelähmte) Hand hatte.',
        2: 'Und sie achteten (man achtete, sie lauerten) genau darauf, ob er ihn [am] Sabbat heilen würde, um gegen ihn Anklage erheben (um ihn anzuklagen) [zu können].',
        3: 'Und er sagte zu dem Mann mit der verkümmerten (gelähmten, verdorrten) Hand: „Komm (Steh auf) in die Mitte!“',
        4: 'Und er fragte (sagte) sie (zu ihnen): „Ist es richtig (erlaubt), [am] Sabbat Gutes zu tun oder Schlechtes zu tun? Leben zu retten oder zu töten?“Aber sie schwiegen (sagten nichts).',
        5: 'Da (Und) blickte (schaute) er sie voll Zorn (zornig) alle der Reihe nach (ringsum) an. Tief betrübt (voller Mitleid) über die Verstockung (Sturheit, Härte) ihrer Herzen, sagte er zu dem Mann: „Strecke die Hand aus!“Und (Da) er streckte [sie] aus und seine Hand wurde wieder gesund (wiederhergestellt).',
        6: 'Und (Doch) sobald die Phärisäer hinausgegangen waren, fassten sie unverzüglich ihn betreffende (gegen/über ihn) Pläne (den Beschluss, berieten) mit den Herodianern (Anhängern von Herodes), wie sie ihn beseitigen (zerstören, töten, aus dem Weg räumen, loswerden) [könnten].',
        7: 'Und (Daraufhin) Jesus zog sich mit seinen Jüngern zum Meer (See) zurück, und eine große Menge aus Galiläa folgte [ihnen], auch (und) aus Judäa,',
        8: '{und aus} Jerusalem, {und aus} Idumäa und [dem Land] jenseits des Jordans, sowie der [Gegend] um Tyrus und Sidon kam eine große Menge zu ihm, die (weil/als sie) hörten, was ([alles], das; wie viel) er tat.',
        9: 'Und er sprach zu seinen Jüngern, damit ihm wegen der Menschenmenge ein kleines Boot bereitstehen würde, damit sie ihn nicht erdrückten,',
        10: 'denn er heilte (hatte geheilt) so viele, dass sich diejenigen ([alle], solche), die Leiden (Qualen) hatten, sich um ihn drängten (sich auf ihn stürzten), um ihn zu berühren.',
        11: 'Und die unreinen Geister fielen vor ihm nieder, sobald sie ihn sahen, und schrien {und sagten} {dass}: „Du bist der Sohn Gottes!“',
        12: 'Und er drohte (befahl, wies an) ihnen nachdrücklich (streng), damit sie ihn nicht bekannt machten.',
        13: 'Dann (Und) stieg er auf den Berg und rief diejenigen zu sich, die er selbst sich ausgesucht hatte; und sie kamen zu ihm.',
        14: 'Und er bestimmte (berief, setzte ein) zwölf, damit sie mit ihm seien und damit er sie zum Predigen (Verkündigen) aussenden [könnte]',
        15: 'und [damit sie] Macht (Vollmacht, Autorität, Ermächtigung) zum Austreiben [von] Dämonen hätten.',
        16: 'Und er bestimmte (berief, setzte ein) die Zwölf, und er gab Simon [den] Namen „Petrus“;',
        17: 'und Jakobus, den [Sohn] von Zebedäus, und Jakobus’ Bruder Johannes, und er gab ihnen [die] Namen „Boanerges“, das heißt „Söhne des Donners“;',
        18: 'weiter (und) Andreas, {und} Philippus, {und} Bartholomäus, {und} Matthäus, {und} Thomas, {und} Jakobus, den [Sohn] von Alphäus, sowie (und) Thaddäus, {und} Simon den Eiferer (Zeloten)',
        19: 'und Judas Iskariot, der ihn dann (auch) auslieferte (verriet).',
        20: 'Später (Und) ging [Jesus] nach Hause (in ein Haus). Und wieder versammelte sich die Menschenmenge, sodass sie nicht einmal dazu kamen, [etwas] Brot zu essen.',
        21: 'Und als seine Angehörigen (Anhänger) [davon] erfuhren ([das] hörten), machten sie sich auf den Weg, um ihn mit Gewalt zurückzuholen (zurückzuhalten, festzuhalten). Sie meinten (sagten) nämlich {dass}: „Er hat den Verstand verloren!“(meinten nämlich, er habe den Verstand verloren.)',
        22: 'Und (Dann) die Schriftgelehrten (Schreiber), die aus Jerusalem gekommen waren, verbreiteten (meinten, sagten) {dass}: „Er ist von Beelzebul besessen!“und {dass}: „Er treibt die Dämonen mit (mithilfe) dem Fürsten (Herrscher, Obersten) der Dämonen aus!“',
        23: 'Und er rief sie zu sich und argumentierte (redete, sagte) mithilfe (in Form von) [einiger] bildhafter Vergleiche (in Gleichnissen) zu ihnen: „Wie kann Satan [den] Satan austreiben?',
        24: 'Und wenn ein Königreich (Reich, Staat) sich mit sich selbst verfeindet, [dann] kann jenes Königreich (Reich, Staat) nicht bestehen.',
        25: 'Und wenn eine Familie (Haus) sich mit sich selbst verfeindet, [dann] wird jene Familie (Haus) nicht bestehen können.',
        26: 'Und wenn [wirklich] der Satan gegen sich selbst rebelliert (auflehnt, erhebt) und sich mit sich selbst verfeindet, [dann] kann er nicht bestehen bleiben, sondern es hat ein Ende [mit ihm].',
        27: 'Doch niemand kann in das Haus des Starken eindringen (einbrechen, hineingehen) und seine Einrichtung (Besitztümer, Hausrat) plündern, wenn er den Starken nicht zuerst fesselt, dann erst kann er sein Haus ausplündern.',
        28: 'Ja (Amen, Wahrlich), ich sage euch {dass}: Den Kindern (Söhnen) der Menschen kann (wird) alles vergeben werden – alle Sünden (Verfehlungen) und Gotteslästerungen, welche (wie viele) sie auch lästern (begehen, aussprechen) mögen.',
        29: 'Doch wer immer gegen den Heiligen Geist lästert, [für] den gibt es in {der} Ewigkeit (im kommenden Zeitalter) keine Vergebung, sondern er ist ewiger Sünde schuldig!“',
        30: '[Das fügte Jesus hinzu,] weil sie sagten: „Er ist [von] einem unreinen Geist besessen!“',
        31: 'Dann (Und) kamen seine Mutter und seine Geschwister (Brüder). {und} Sie blieben draußen stehen (standen) und schickten [jemanden] zu ihm (ließen ihm ausrichten), um (wobei sie) ihn zu rufen.',
        32: '{und} Eine Menschenmenge saß um ihn herum, und sie sagten (man sagte) zu ihm: „Da draußen fragen deine Mutter und deine Geschwister (Brüder) nach (suchen nach, wollen etwas von) dir!“',
        33: 'Und er antwortete ihnen {und sagte}: „Wer sind meine Mutter und meine Geschwister (Brüder)?“',
        34: 'Und während (indem, nachdem) er der Reihe nach [alle] anschaute, die [im] Kreis (rings) um ihn saßen, sagte er: „Siehe, (Das hier sind, Ihr hier seid) meine Mutter und meine Geschwister!',
        35: 'Denn wer immer den Willen Gottes tut, der ist mein Bruder und [meine] Schwester und [meine] Mutter.“',
    },
    4: {
        1: 'Und wieder einmal (erneut) begann er am Meer (See) zu lehren. Und eine so gewaltige Menschenmenge versammelte sich bei ihm, dass er in ein Boot stieg und [darin] auf dem Meer (See) saß, und die ganze Menschenmenge blieb (war) am Ufer an Land.',
        2: 'Und er lehrte sie mit (mithilfe, in) Gleichnissen (bildhaften Vergleichen) viele [Dinge] (lange) und er sagte zu ihnen, während er lehrte (bei/in/während seiner Lehre):',
        3: '„Hört! Seht! (Einmal) Der Säende (Sämann) machte sich auf, [um] zu säen.',
        4: 'Und beim Säen kam es dazu (geschah es), [dass] ein [Teil des Saatguts] ([Samenkorn]) an den Wegesrand (auf den Weg) fiel, und die Vögel kamen und fraßen es auf.',
        5: 'Und ein anderer [Teil] fiel auf felsigen Boden, wo er nicht viel Erde hatte, und [die Saat] ging schnell auf, weil sie keine tiefe Erde hatte.',
        6: 'Doch (und) als (nachdem) die Sonne aufging (hochstieg), wurde [die Saat] versengt, und weil sie keine Wurzeln hatte, verdorrte sie (trocknete sie aus).',
        7: 'Und ein anderer [Teil] fiel zwischen die Dornengewächse (Dornbüsche, Dornen), und die Dornengewächse (Dornbüsche, Dornen) wuchsen auf (überwucherten) und erstickten [die Saat], und sie brachte keine Frucht.',
        8: 'Und andere [Körner] ([Teile]) fielen auf {den} guten Boden (Erde) und brachten Frucht, indem (während, wobei) sie aufgingen (aufwuchsen) und wuchsen, und ein [Samenkorn] ([Teil der Saat]) brachte 30, {und} eins 60 und eins 100 [Körner] hervor ([das Saatgut] trug dreißig- {und}, sechzig- und hundertfach [Frucht]).“',
        9: 'Dann (und) sagte er: „Wer Ohren hat [zum] Hören, soll hören (höre)!“',
        10: 'Und wenn (als) er für sich alleine war, fragten ihn [die Leute], die um ihn [waren], mit den Zwölfen [immer wieder nach] den Gleichnissen (Vergleichen).',
        11: 'Dann (und) sagte er zu ihnen: „Euch ist das Geheimnis von Gottes Königreich (Königsherrschaft) gegeben, aber denen draußen (den Außenstehenden) wird alles in (mit, mit Hilfe von) Gleichnissen (Vergleichen, Rätseln) vermittelt,',
        12: 'damit [sie] sehen und (obwohl sie sehen; beim Sehen) sehen und (aber) nicht erkennen, und hören und (obwohl sie hören; beim Hören), hören und (aber) nicht verstehen, damit sie nicht etwa umkehren (sich bekehren) und ihnen vergeben wird.“',
        13: 'Und er sagte zu ihnen: „Begreift ihr dieses Gleichnis (Vergleich) nicht? Wie [wollt] ihr dann (und) überhaupt (all die [anderen]) Gleichnisse (Vergleiche) verstehen?',
        14: 'Der Säende (Sämann) sät das Wort (die Botschaft).',
        15: '{und (aber) } Die am Wegesrand (auf dem Weg) sind diejenigen, in die (wo) das Wort (die Botschaft) gesät wird, und sobald sie [es] hören, kommt der Satan und nimmt das in (auf) sie hineingesäte Wort (Botschaft) gleich (schnell) wieder weg.',
        16: 'Und die auf den felsigen Boden Gesäten sind diejenigen, die das Wort (Botschaft) gleich mit Freuden annehmen, sobald sie es hören,',
        17: 'aber (und) keine Wurzel in sich haben, sondern unbeständig sind. Wenn es dann wegen des Wortes (der Botschaft) zu Leid (Bedrängnis, Schwierigkeiten) oder Verfolgung kommt, geben sie bald (schnell, gleich) auf (wenden sich/fallen ab, kommen zu Fall, ärgern sich).',
        18: '{und} Andere sind die unter die Dornengewächse (Dornbüsche, Dornen) Gesäten. Es sind diejenigen, die das Wort (die Botschaft) hören (gehört haben),',
        19: 'und (aber) wenn weltliche Sorgen (Sorgen der Gegenwart, Zeit), {und} die Verlockung (Täuschung) des Reichtums und das Verlangen (die Gier, Sehnsucht) nach allem anderen dazukommen (sich breit machen), ersticken sie das Wort (die Botschaft) und (sodass) es wird unfruchtbar.',
        20: 'Und die auf die gute Erde gesät werden, sind jene, die das Wort (die Botschaft) hören und annehmen und Frucht bringen, eines 30, {und} eines 60 und eines 100 (dreißigfach, {und} sechzigfach und hundertfach).“',
        21: 'Und (Dann) er sagte zu ihnen: „Bringt man etwa [eine] Lampe, um sie unter [einen] Behälter (Scheffel, Gefäß, Schüssel, Eimer) oder unter das Bett (Liege, Sofa) zu stellen? Oder doch eher (Nein), um sie auf den Lampenständer (Leuchter) zu stellen?',
        22: 'Denn es gibt nichts Verborgenes (Verstecktes, Geheimes), außer um es öffentlich (offenbar, sichtbar) zu machen, und es ist auch nichts geheim (verborgen) geworden (geschehen), außer um ins Tageslicht (Offene) zu kommen.',
        23: 'Wer Ohren hat [zum] Hören, soll hören (höre)!“',
        24: 'Und (Dann) er sagte zu ihnen: „Achtet auf [das], was ihr hört! Mit dem Maß, mit dem ihr messt (zuteilt), wird euch [euer Teil] zugemessen (zugeteilt) werden, und euch wird noch mehr gegeben werden.',
        25: 'Denn wer hat, dem wird gegeben und wer nicht hat, {von} dem wird auch das, [was] er hat, weggenommen werden.“',
        26: 'Und (Dann) er sagte: „Gottes Königreich (Königsherrschaft) ist so, wie wenn ein Mann die Saat ([einen] Samen) auf das Ackerland (den Boden) streut (wirft, fallen lässt).',
        27: 'Während (dann, und) er schläft und erwacht, Nacht und Tag, {und} sprießt und wächst die Saat (der Same) – wie (während), [das] weiß er selbst nicht (ohne daß er selbst etwas davon weiß).',
        28: 'Von selbst bringt die Erde Frucht, zuerst einen Halm, dann eine Ähre, dann mit voll ausgereiftem Weizen in der Ähre.',
        29: 'Und (aber) sobald die Frucht es zulässt, setzt er gleich (bald) die Sichel an (sendet aus), weil die Erntezeit gekommen ist.“',
        30: 'Und (Dann) sagte er: „Womit können wir Gottes Königreich (Königsherrschaft) vergleichen, oder mit (in) welchem Bild (Gleichnis, Vergleich) können wir es darstellen?',
        31: 'Mit einem Senfkorn, das, wenn es in (auf) die Erde gesät wird, [das] kleinste (kleiner [als]) aller Samenkörner ist, die [man] in (auf) die Erde [sät],',
        32: 'und wenn es gesät ist, geht es auf (wächst es nach oben) und wird [die] größte (größer [als]) aller Gartenpflanzen, und es treibt so große Zweige, dass in seinem Schatten die Vögel des Himmels nisten (Unterschlupf finden) können.“',
        33: 'So (Und) erläuterte (verkündete, sagte) er ihnen mit (in) vielen solchen Gleichnissen (Bildern, Vergleichen) [seine] Botschaft (das Wort) so, wie (in einer Weise, dass; in dem Maße, wie) sie [sie] verstehen (hören) konnten.',
        34: 'Dabei sprach (verkündete) er nie ohne Gleichnis (Bild, Rätsel, Vergleich) mit (zu) ihnen, doch [wenn er] mit seinen Jüngern alleine [war], erklärte er (löste auf, legte aus) alles.',
        35: 'Und an jenem Tag sagte er zu ihnen, als es Abend geworden war: „Fahren wir doch (lasst uns) ans andere Ufer.“',
        36: 'Und nachdem sie die Menschenmenge weggeschickt hatten (wobei … zurückließen), nahmen sie ihn im Boot mit (zu sich ins Boot), wie er war, und auch andere Boote waren bei ihm.',
        37: 'Da (und) kam ein starker Sturmwind auf, und die Wogen schlugen [bald] so [heftig], [auch] in das Boot, dass das Boot sich schon [langsam] füllte.',
        38: 'Er befand sich währenddessen am Heck, wo er auf dem Kissen schlief, und sie weckten ihn und riefen (sagten) {zu ihm}: „Lehrer, kümmert es dich nicht, dass wir umkommen?“',
        39: 'Da (und) wachte er auf, unterwarf (fuhr an) den Wind und rief (sagte) dem Meer (See) zu: „Still, sei ruhig!“Und der Wind ließ nach, und es trat eine große Stille ein.',
        40: 'Und er sagte zu ihnen: „Warum seid ihr [so] furchtsam (verzagt)? Habt ihr noch keinen Glauben (Vertrauen)?“',
        41: 'Da (Und) fürchteten sie sich [mit] großer Furcht (Ehrfurcht) und sagten zueinander: „Wer ist denn dieser [Mann], dass sogar der Wind und das Meer (der See) ihm gehorchen?“',
    },
    5: {
        1: 'Und sie kamen ans andere Ufer des Meeres (Sees), in das Gebiet (Land) der Gerasener (Gergesener, Gadarener).',
        2: 'Und als er gerade (gleich, bald) aus dem Boot (Schiff) gestiegen war (stieg), kam von den Grabstätten (Gräbern, Grabhöhlen) her ein Mann mit einem unreinen Geist auf ihn zu (ihm entgegen),',
        3: 'der [seine] Behausung (Unterkunft, Lager) in den Grabhöhlen (Grabstätten, Gräbern) hatte, und nicht einmal (auch nicht) [mit] einer Kette konnte man ihn noch bändigen (festhalten, fesseln).',
        4: 'Er war nämlich schon mehrfach [mit] Fußfesseln und Ketten (Handfesseln) gefesselt worden und (aber) hatte [jedes Mal] die Ketten (Handfesseln) zerrissen und die Fußfesseln zerrieben (zerschmettert), und niemand war stark [genug], ihn unter Kontrolle zu bringen (zu bezwingen, überwältigen, bändigen).',
        5: 'Und die ganze Zeit (ununterbrochen, ständig), nachts wie tags, hielt er sich (war) in den Grabhöhlen (Grabstätten, Gräbern) oder (und) in den Bergen auf, wo (wobei, während) er schrie (schrie er in den Grabhöhlen oder in den Bergen) und sich [mit] Steinen schnitt (verletzte; auf sich einschlug).',
        6: 'Und als (weil) er Jesus von Weitem sah, kam er angerannt und warf sich vor ihm nieder.',
        7: '{und} Er schrie [mit] lauter Stimme und sagte: „Was willst du von mir, Jesus, Sohn Gottes, des Höchsten (des höchsten Gottes)? Ich beschwöre dich bei Gott, mich nicht zu quälen (foltern)!“',
        8: 'Denn [Jesus] hatte zu ihm gesagt (sagte gerade/wiederholt): „Komm heraus (Fahre aus, verlass) aus dem Mann, unreiner Geist!“,',
        9: 'und er fragte ihn: „Was [ist] dein Name?“, und er antwortete (sagte) {zu ihm}: „Mein Name [ist] »Legion«, denn wir sind viele.“',
        10: 'Und er flehte (bat) ihn immer wieder (inständig) an, {dass} sie nicht aus der Gegend (Gebiet, Land) wegzuschicken (zu vertreiben).',
        11: 'Nun (aber, und) weidete (wurde gehütet) in der Nähe (dort) am Berghang gerade eine große Schweineherde.',
        12: 'Und sie baten (flehten an) ihn {sagend}: „Schicke (Treibe) uns in die Schweine! Wir wollen (damit wir) in sie fahren!“,',
        13: 'und er erlaubte [es] ihnen. Da (Und) fuhren die unreinen Geister aus und fuhren in die Schweine, und die Herde raste (stürzte sich, stürmte) den Abhang hinunter ins Meer (den See), ungefähr zweitausend, und ertranken im Meer (See).',
        14: 'Und ihre Hirten ergriffen die Flucht (liefen davon) und verbreiteten (verkündeten, erzählten) [die Nachricht] in der Stadt und auf dem Land (den Höfen, Dörfern). Und [die Leute] machten sich auf (kamen), [um] zu sehen, was das Geschehene war.',
        15: 'Und sie erreichten (kamen zu) Jesus und sahen (als sie erreichten, sahen sie), dass der Besessene saß, bekleidet und bei Verstand – derjenige, der die Legion gehabt hatte! – und fürchteten sich.',
        16: 'Und die, die [alles] gesehen hatten, erzählten (schilderten) ihnen, was (wie) mit dem Besessenen passierten war, und von den Schweinen.',
        17: 'Da (Und) drängten (baten, forderten auf) sie ihn, ihr Gebiet zu verlassen (fortzugehen aus).',
        18: '{Und} Als er ins Boot stieg, bat (flehte) ihn der, der besessen gewesen war, darum, {dass} bei ihm bleiben [zu dürfen].',
        19: 'Aber (und) er erlaubte es ihm (ließ ihn) nicht, sondern sagte zu ihm: „Geh nach Hause (in dein Haus) zu den Deinen und berichte (verkünde, erzähle) ihnen, was der Herr dir getan hat und [wie] er Erbarmen mit dir hatte!“',
        20: 'Und (Da) er ging fort und begann in der Dekapolis (im Zehnstädtegebiet) zu erzählen (predigen, verkündigen), was Jesus ihm getan hatte, und alle staunten (wunderten sich).',
        21: 'Und nachdem Jesus mit dem (im) Boot wieder (zurück) ans andere Ufer gefahren war, versammelte sich eine große Menschenmenge bei ihm. {und} Er war gerade (während, noch) am Meer (See),',
        22: 'als (da, und) einer der Synagogenvorsteher namens Jairus kam, und als er ihn sah, warf (fiel) er sich ihm vor die Füße',
        23: 'und bat (flehte an) ihn inständig (mehrfach) {sagend}: „Meine kleine Tochter ist dem Tode nahe (liegt im Sterben, ist todkrank) – komm doch und lege ihr deine Hände auf, damit sie gerettet (geheilt) wird und am Leben bleibt (lebt)!“',
        24: 'Und er ging mit ihm, und eine große Menge folgte ihm, und sie drängten sich um ihn.',
        25: 'Und eine Frau, die [seit] zwölf Jahren an Blutungen (Blutfluss) litt',
        26: 'und mit (durch) vielen Ärzten viel durchgemacht (erduldet, erlitten) hatte, die ihren gesamten Besitz (Vermögen, Habe) ausgegeben hatte, ohne etwas zu erreichen (einen Nutzen davon zu haben); stattdessen (im Gegenteil) war es ihr immer schlechter gegangen (schlimmer geworden),',
        27: 'als sie (die) von Jesus hörte, näherte sich (kam) [diese Frau] in der Menge von hinten und berührte (fasste an) seine Kleidung (Gewand).',
        28: 'Sie sagte sich (dachte) nämlich: „Wenn ich auch nur seine Kleider (Kleidung) berühre (anfasse), werde ich geheilt (gerettet) werden!“',
        29: 'Und die Quelle ihre Blutes versiegte (vertrocknete) auf der Stelle (sofort), und sie bemerkte (wusste, spürte) [an (in) ihrem] Körper, dass sie von [ihrem] Leiden (Qual) geheilt war.',
        30: 'Und Jesus, der (als/weil er) innerlich (bei sich) sofort merkte, dass Kraft [von ihm] ausgegangen war, drehte sich in der Menschenmenge um und fragte (sagte, wiederholte): „Wer hat meine Kleider (Kleidung) berührt (angefasst)?“',
        31: 'Aber (Und, Da) seine Jünger meinten (sagten) {ihm}: „Du siehst die Menschenmenge, die sich um dich drängt, und sagst: »Wer hat mich berührt (angefasst)?«“',
        32: 'Und er schaute sich um, [um] die [Person] zu sehen, die es gewesen war (getan hatte).',
        33: 'Die Frau fürchtete sich und zitterte, weil sie wusste, was mit ihr passiert war. Sie kam und warf sich (fiel) vor ihm nieder und erzählte (sagte) ihm die ganze Wahrheit.',
        34: 'Doch er sagte zu ihr: „Tochter, dein Glaube (Vertrauen) hat dich gesund gemacht (gerettet). Geh in Frieden, und sei (bleibe) von deinem Leiden (Plage) gesund (geheilt)!“',
        35: 'Während er noch redete, kamen [Angehörige (Leute aus dem Haus)] des Synagogenvorstehers und richteten aus (sagten): „Deine Tochter ist gestorben. Was (Warum) bemühst du noch den Lehrer?“',
        36: 'Aber Jesus, der mitbekommen hatte (hörte zu; überhörte, missachtete), wie die Botschaft (Meldung, Wort) ausgerichtet (gesagt) wurde, sagte zu dem Synagogenvorsteher: „Fürchte dich nicht, vertraue (glaube) einfach (nur)!“',
        37: 'Und er ließ (erlaubte) niemanden mitkommen (ihn begleiten) außer Petrus, {und} Jakobus und Jakobus’ Bruder Johannes.',
        38: 'Als (Und) sie zum (in das) Haus des Synagogenvorstehers kamen, {und} sah er ein lärmendes Durcheinander (Aufregung, Tumult) und [Menschen], die heftig heulten (weinten) und wehklagten (heulten),',
        39: 'und nach dem (beim) Eintreten sagte er zu ihnen: „Warum seid ihr so erregt (lärmt) und heult (weint)? Das Kind (Kindlein) ist nicht tot, sie schläft nur!“',
        40: 'Da (Und) lachten sie ihn aus. Doch [Jesus] schickte (trieb, warf) alle hinaus, dann nahm er den Vater und die Mutter des Kindes (Kindleins) und [alle], die bei ihm [waren], mit und ging in [das Zimmer], wo sich das Kind (Kindlein) befand.',
        41: '{Und} Er nahm die Hand des Kindes (Kindleins) und sagte zu ihr: „Talita kum!“, das heißt übersetzt: „Mädchen, ich sage dir, steh (wach) auf!“',
        42: '{Und} Das Mädchen erhob sich auf der Stelle (sofort) und begann umherzugehen; sie war nämlich zwölf Jahre [alt]. {Und} Da (sofort) waren [alle vor] lauter Fassungslosigkeit (Entgeisterung, Verblüffung, Entsetzen) [ganz] fassungslos (außer sich, entgeistert, erstaunt).',
        43: 'Und er machte ihnen unmissverständlich (mehrmals, ausdrücklich) klar (ordnete an, schärfte ein), dass niemand davon erfahren [dürfe], zudem (und) sagte er, [man solle] ihr [etwas] zu Essen geben.',
    },
    6: {
        1: 'Und er ging von dort weg und begab sich (kam) in seine Heimat (Heimatstadt), wobei (und) seine Jünger ihn begleiteten (ihm folgten).',
        2: 'Und als [der] Sabbat gekommen (geworden) war, begann er, in der Synagoge zu lehren (lehrte er), und viele, die zuhörten, waren überwältigt (überrascht, erstaunt, außer sich) und sagten: „Wo [hat] er das her, und was [ist] die Weisheit, die ihm gegeben wurde – und (und [wie kommt es, dass]) solche Wunder (Wunderkräfte), die durch seine Hände geschehen!',
        3: 'Ist das nicht der Zimmermann (Handwerker, Baumeister), der Sohn von Maria und der Bruder von Jakobus und Joses, {und} Judas und Simon? Und leben (sind) seine Schwestern nicht hier bei uns?“Und sie lehnten ihn ab (ärgerten sich über, nahmen Anstoß an).',
        4: 'Und Jesus sagte zu ihnen: „Ein Prophet ist nirgends (nicht) ohne Ansehen (Ehre), außer in seiner Heimat (Heimatstadt), {und} bei seinen Verwandten und in seiner Familie (Haus, Haushalt).“',
        5: 'So (Und) konnte er dort kein einziges Wunder (Wunderkraft) tun, außer dass (nur) er einigen Kranken die Hände auflegte und sie heilte,',
        6: 'und er wunderte sich über ihren Unglauben. Und (Dann) er zog durch die Dörfer ringsum und lehrte.',
        7: 'Und er rief die Zwölf zu sich und sandte sie paarweise aus, und er gab ihnen Macht (Vollmacht) über die unreinen Geister,',
        8: 'und er gab ihnen die Anweisung (bestimmte), {dass} nichts auf den Weg mitzunehmen als nur einen Wanderstab – kein Brot, keine Tasche, kein Geld im Gürtel,',
        9: 'dabei jedoch (sondern) Sandalen zu tragen, „und zieht keine zwei Unterhemden an!“',
        10: 'Und er sagte zu ihnen: „Wo ihr in ein Haus eintretet (einkehrt, hineingeht), [da] bleibt dort, bis ihr {von dort} [wieder] aufbrecht (weggeht).',
        11: 'Und nimmt man euch an einem Ort nicht auf und hört euch auch nicht zu, dann schüttelt beim Aufbruch (geht von dort weg und) den Staub von euren Schuhsohlen ab, als Zeugenaussage (Beweis, Zeichen, Zeugnis) [gegen (für)] sie!“',
        12: 'Und sie machten sich auf den Weg (gingen los) und predigten (verkündigten), {dass} [die Menschen sollten] umkehren (Buße tun).',
        13: 'Zudem (Und) trieben sie viele Dämonen aus, und sie salbten viele Kranke [mit] Öl und heilten sie.',
        14: 'Und König Herodes hörte [von Jesus], denn sein Name (Ruf, Ansehen) war bekannt geworden, und [die Leute] meinten (sagten): „Johannes der Täufer ist von [den] Toten auferweckt worden. Das erklärt, warum die Wunderkräfte durch ihn (in ihm) wirken!“',
        15: 'Andere sagten dagegen (und): „Er ist Elija“, und wieder andere meinten (sagten): „Ein Prophet wie einer der [alten] Propheten.“',
        16: 'Als Herodes [das] hörte, glaubte (sagte, rief) er: „Der, den ich enthauptet habe, Johannes, ist auferweckt worden!“',
        17: 'Herodes selbst hatte Johannes nämlich gefangen nehmen und ihn im Gefängnis festgehalten (gefesselt ins Gefängnis [werfen]) lassen. [Das tat er] wegen Herodias, der Frau seines Bruders Philippus, weil er sie geheiratet hatte.',
        18: 'Johannes hatte nämlich [wiederholt] zu Herodes gesagt: „Es ist dir nicht erlaubt, die Frau deines Bruders zu haben!“',
        19: 'Aber Herodias nahm ihm [das] übel und plante (wollte), ihn zu töten, hatte aber (und) lange keine Gelegenheit dazu (es gelang ihr nicht).',
        20: 'Denn Herodes respektierte (fürchtete) Johannes, weil er wusste, [dass] er ein gerechter und heiliger Mann [war], und er beschützte ihn (hielt ihn in Haft), und wenn er ihm zuhörte (zugehört hatte), war er immer wieder (jedes Mal) stark verunsichert (ratlos, verwirrt, verlegen), aber (und) er hörte ihm gerne zu.',
        21: 'Und als ein günstiger Tag kam, als Herodes [anlässlich] seines Geburtstages für seine Würdenträger (Hofbeamten), {und} die Offiziere (Hauptleute) und Galiläas angesehenste Bürger ein Festmahl veranstaltete,',
        22: 'und als die Tochter eben jener Herodias (seine Tochter Herodias) hereinkam und tanzte, gefiel [sie] Herodes und seinen Tischgästen (denen, die mit [ihm] aßen/ [zu Tisch] lagen). Der König sagte zu dem Mädchen: „Bitte (wünsche, verlange) mich, was auch immer du willst, und ich werde [es] dir geben!“',
        23: 'Und er schwor ihr (schwor ihr mehrmals/eindringlich): „Worum du mich auch bittest (wünscht, verlangst), ich werde es dir geben, bis zur Hälfte meines Reiches!“',
        24: 'Und sie ging hinaus und fragte (sagte zu) ihre Mutter: „Was soll ich mir wünschen (bitten, verlangen)?“, und sie sagte: „Den Kopf von Johannes dem Täufer!“',
        25: 'Und sofort ging sie eilig [wieder] hinein zum König und verlangte (bat [ihn]) {sagend}: „Ich will, dass du mir umgehend den Kopf von Johannes dem Täufer auf einer Schale (Teller) gibst!“',
        26: 'Und der König wurde sehr traurig, aber wegen seiner Schwüre und der Gäste ([zu Tisch] Liegenden) wollte er sie nicht abweisen.',
        27: 'Also schickte der König einen Henker und ordnete an, seinen Kopf herzubringen. Und er ging los und enthauptete ihn im Gefängnis,',
        28: 'dann (und) brachte er seinen Kopf auf einer Schale [herein] und gab ihn dem Mädchen, und das Mädchen gab ihn ihrer Mutter.',
        29: 'Und als seine Jünger [davon] erfuhren (hörten), kamen sie, {und} holten seinen Leichnam ab und legten ihn in ein Grab.',
        30: 'Und die Apostel (ausgesandten [Jünger]) kamen bei Jesus zusammen und berichteten ihm alles, was sie getan und was sie gelehrt hatten.',
        31: "Und er sagte zu ihnen: „Kommt ''ihr'' doch ganz allein [mit mir] an einen abgelegenen Ort und ruht euch ein wenig aus!“Denn es waren viele, die kamen und gingen, und sie fanden nicht einmal Zeit zum Essen.",
        32: 'Und sie fuhren (brachen auf) mit (in) dem Boot an einen einsamen Ort, ganz allein.',
        33: 'Allerdings (und) sahen [die Leute], wie sie losfuhren (aufbrachen), und viele erkannten [ihre Absicht (sie)] (erfuhren [davon]), und zu Fuß liefen sie aus allen Städten zusammen und kamen (liefen voraus) vor ihnen an ihrem Zielort (dort) an.',
        34: 'Und als er ausstieg, sah er eine große Menschenmenge, und er empfand Mitleid mit ihnen, weil sie wie Schafe waren, die keinen Hirten haben, und er begann, sie vieles (lange) zu lehren.',
        35: 'Und als (weil) die Stunde schon spät geworden war, kamen seine Jünger zu ihm und sagten: „Diese Gegend (Ort) ist abgelegen und die Stunde ist schon spät –',
        36: 'verabschiede (schick weg, entlasse) [die Leute] [doch], damit sie zu den umliegenden Bauernhöfen und Dörfern gehen und sich etwas zu essen kaufen [können].“',
        37: 'Doch (Und) er antwortete {und sagte} ihnen: „Gebt ihr ihnen [doch] zu essen!“Und (Da) sie sagten zu ihm: „Sollen wir losgehen und [für] zweihundert Denare Brote kaufen und ihnen zu essen geben?“',
        38: 'Und er sagte zu ihnen: „Wie viele Brote habt ihr? Geht [und] schaut nach!“Und nachdem sie [es] festgestellt hatten, sagten sie: „Fünf, und zwei Fische.“',
        39: 'Daraufhin (Und) wies er sie an (veranlasste er), [dafür zu sorgen, dass] sich alle in Gruppen auf das grüne Gras setzten.',
        40: 'Und sie nahmen in Gruppen von hundert und von fünfzig [Personen] Platz.',
        41: 'Und er nahm die fünf Brote und die zwei Fische, blickte auf zum Himmel und segnete [sie]. Dann (und) brach er die Brote auseinander und gab sie seinen Jüngern, um sie {ihnen} auszuteilen. Auch (und) die zwei Fische verteilte er an alle.',
        42: 'Und alle aßen und wurden satt,',
        43: 'und sie hoben zwölf große Körbe voller Brocken auf, auch von den Fischen.',
        44: 'Und diejenigen, die die Brote gegessen hatten, waren fünftausend Männer.',
        45: 'Und kurze Zeit später (gleich danach) nötigte er seine Jünger, in das Boot zu steigen und an das andere (gegenüberliegende) Ufer nach (Richtung) Betsaida vorauszufahren, während er selbst die Menschenmenge verabschieden wollte.',
        46: 'Und nachdem er sich von ihnen verabschiedet hatte, ging er weg auf den Berg, [um] zu beten.',
        47: 'Und als es Abend geworden war, befand sich (war) das Boot mitten auf dem Meer (See), und er allein an Land.',
        48: 'Und weil (als) er sah, dass sie sich beim Vorwärtskommen (Rudern) quälten, denn der Wind war {ihnen} widrig ([wehte] ihnen entgegen), da kam er um die vierte Nachtwache in ihre Richtung, indem er auf dem Meer lief. Dabei (und) wollte er an ihnen vorbeigehen.',
        49: 'Und als sie ihn auf dem Meer (See) laufen sahen, meinten sie, dass es ein Gespenst sei, und schrien auf (fingen an zu schreien).',
        50: 'Denn alle sahen ihn und erschraken. Doch er begann sofort mit ihnen zu reden. {und} Er sagte zu ihnen: „Keine Angst! (Beruhigt euch!, Habt Vertrauen!) Ich bin [es], fürchtet euch nicht!“',
        51: 'Und er stieg zu ihnen ins Boot, und der Wind legte sich/flaute ab. Da (Und) innerlich selbst waren sie ganz (ganz außerordentlich) fassungslos (überwältigt, entgeistert, erschüttert, außer sich).',
        52: 'Sie verstanden (hatten verstanden) nämlich nicht, was es mit den Broten auf sich hatte, sondern ihr Herz war verstockt (verhärtet).',
        53: 'Und nachdem sie übergesetzt hatten, gingen sie in Gennesaret an Land und landeten (legten an, ankerten, liefen in den Hafen, zogen [das Boot] an Land).',
        54: 'Und als sie aus dem Boot stiegen, erkannten [die Leute] ihn sofort und',
        55: 'eilten (liefen) durch die gesamte Gegend, und sie trugen (fingen an zu tragen) diejenigen, denen es schlecht ging (die Kranken) auf [ihren] Matten [immer] dorthin, wo sie hörten, dass er war.',
        56: 'Und wo er auch hinging, in Dörfer, {oder} in Städte oder in Bauernhöfe, legten sie die Kranken auf die Marktplätze und baten ihn darum, {dass} auch nur die Quaste (den Saum) seines Gewandes berühren [zu dürfen]. Und alle, die ihn berührten, wurden geheilt.',
    },
    7: {
        1: 'Und die Pharisäer und einige der Schriftgelehrten (Schreiber), die aus Jerusalem gekommen waren, versammelten sich bei ihm.',
        2: 'Und weil (als) sie gesehen hatten (sahen), dass manche von seinen Jüngern [mit] unreinen, das heißt: [mit] ungewaschenen Händen die Brote (ihr Essen) aßen –',
        3: 'die Pharisäer und die Juden überhaupt (alle) essen nämlich nicht, wenn sie sich nicht sorgfältig (mit einer Handvoll Wasser, in der vorgeschriebenen Weise; mit der Faust) die Hände gewaschen haben, um (Damit, weil) an der Überlieferung der Ältesten (Vorfahren) festzuhalten,',
        4: 'und [nach der Rückkehr] vom Markt essen sie nicht, bis (wenn) sie nicht gebadet (einer Reinigung unterzogen, gewaschen) haben; und es gibt viele andere [Regeln], die sie zu halten übernommen haben, [zum Beispiel] das Abspülen von Bechern, {und} Krügen und Kupfergefäßen und Sitzpolstern (Betten) –',
        5: 'da (und) erkundigten (fragten) die Pharisäer und die Schriftgelehrten sich bei ihm: „Weshalb leben (folgen) deine Jünger nicht nach der Überlieferung der Ältesten, sondern essen das Brot (Essen) [mit] unreinen Händen?“',
        6: 'Aber er sagte zu ihnen: „Richtig (Treffend, Zurecht) hat Jesaja über euch Heuchler (Scheinheilige) geweissagt, wie geschrieben steht: »Dieses Volk ehrt mich [mit] den Lippen, aber ihr Herz ist weit von mir entfernt.',
        7: 'Und sie beten (verehren) mich vergeblich an, weil sie [als verbindliche] Lehren Gebote von Menschen lehren.«',
        8: 'Während ihr Gottes Willen (Gesetz, Gebot) außer Acht lasst, haltet ihr euch [stattdessen (gleichzeitig)] an die Überlieferung der Menschen!“',
        9: 'Und er fuhr fort (sagte) {zu ihnen}: „Geschickt (meisterhaft, trefflich) setzt (hebt auf) ihr Gottes Gebot (Gesetz, Willen) außer Kraft, um eure Überlieferung aufrechtzuerhalten (zur Geltung zu bringen).',
        10: 'Mose hat doch (ja) gesagt: »Ehre deinen Vater und deine Mutter!«, und: »Wer Vater oder Mutter verflucht (schmäht, schlechtmacht, herabsetzt), muss sterben.«',
        11: "''Ihr'' jedoch sagt: »Wenn ein Mann (Mensch) zu [seinem] Vater oder [seiner] Mutter sagt: Alles von mir, was dich unterstützen (helfen, nützen) würde, [ist] Korban!«, das heißt »Opfergabe (Geschenk) «,",
        12: 'dann erlaubt (lasst ihr zu, dass … nicht mehr; lasst) ihr ihm nicht mehr, etwas [für seinen] Vater oder [seine] Mutter tun.',
        13: 'So (indem) hebt (macht nichtig) ihr Gottes Wort (Aussage) auf durch eure Überlieferung, die ihr weitergegeben (überliefert) habt, und ihr tut viele vergleichbare (ähnliche) solche [Dinge] (vergleichbare solche [Dinge] tut ihr häufig).“',
        14: 'Und (Dann) er rief die Menschenmenge wieder (noch einmal) zu sich und sprach nun zu ihnen: „Hört mir alle zu und versteht!',
        15: 'Nichts, was (wenn, indem) von außerhalb des Menschen in ihn hineingelangt, kann ihn verunreinigen (Es gibt nichts, was … hineingelangt, das … kann). Es ist vielmehr, was aus dem Menschen herauskommt, das den Menschen verunreinigt.',
        16: 'Wer Ohren hat [zum] Hören, soll hören (höre)! “',
        17: 'Und als er ein Haus betrat, abseits der Menschenmenge, erkundigten sich seine Jünger bei ihm nach dem Gleichnis.',
        18: 'Und er sagte zu ihnen: „Seid auch ihr so schwer von Begriff (unverständig)? Versteht (Merkt) ihr nicht, dass alles, was von außen in den Menschen gelangt, ihn nicht verunreinigen kann,',
        19: 'weil es nicht in sein Herz gelangt, sondern in seinen Magen (Bauch), und [dann] in den Abtritt (Senkgrube, Latrine) ausgeschieden wird (hinausgelangt)?“So erklärte [Jesus] alle Speisen für rein.',
        20: "{und} Er fuhr fort (sagte): „Was aus dem Menschen herauskommt, ''das'' verunreinigt den Menschen.",
        21: 'Denn von innen her, aus dem Herzen der Menschen, kommen die üblen Vorsätze (Gedanken, Absichten): sexuelle Eskapaden (Unzüchtigkeiten), Diebstähle, Morde,',
        22: 'Seitensprünge (Ehebrüche), Begehrlichkeiten (Gelüste, Machthunger), Bosheiten, Arglist (Hinterlist), Zügellosigkeit (Ausschweifung), ein böses Auge, Verleumdung (Gotteslästerung, Beleidigung), Überheblichkeit [und] Unvernunft –',
        23: 'all diese bösen (schlechten) [Auswüchse] (All dieses Böse) kommen von innen her und verunreinigen den Menschen.“',
        24: 'Und von dort brach (stand) er auf und ging weg in das Gebiet von Tyrus. Und er begab sich in ein Haus und wollte, dass niemand [davon] erfuhr, und er schaffte es nicht, [seine Anwesenheit] verborgen zu halten.',
        25: 'Stattdessen kam gleich, als sie von ihm hörte, eine Frau zu ihm, deren kleine Tochter von einem unreinen Geist besessen war, und warf sich vor seine Füße.',
        26: '{aber} – Die Frau war Nichtjüdin (Griechin), der Herkunft [nach] eine Syrophönizierin. – Und sie bat ihn hartnäckig (immer wieder) darum, den Dämon aus ihrer Tochter auszutreiben.',
        27: 'Aber (Und) er sagte zu ihr: „Lass zunächst die Kinder satt werden, denn es ist nicht richtig, den Kindern das Brot wegzunehmen und es den Hunden hinzuwerfen.“',
        28: 'Doch sie entgegnete {und sagte zu ihm}: „Ja, Herr (Herr), auch die Hunde unter dem Tisch fressen die Krümel (Reste) der Kinder.“',
        29: 'Und er sagte zu ihr: „Weil du das gesagt hast, geh! Der Dämon hat deine Tochter verlassen.“',
        30: 'Und sie ging zurück in ihr Haus und stellte fest, dass das Kind im Bett lag und der Dämon weg (ausgefahren) war.',
        31: 'Und (Später) er verließ das Gebiet von Tyrus wieder und reiste (kam) durch Sidon ans Meer (See) von Galiläa, mitten durch (in) das Gebiet der Dekapolis (Zehnstädtegebiet).',
        32: 'Und [die Leute] brachten einen Taubstummen zu ihm und baten (forderten auf) ihn, ihm die Hand aufzulegen.',
        33: 'Und er nahm ihn beiseite, abseits der Menschenmenge, [wo sie] unter sich [waren], und steckte ihm seine Finger in die Ohren. Dann (und) spuckte er und berührte seine Zunge.',
        34: 'Schließlich (und) blickte er zum Himmel auf und seufzte (stöhnte), dann (und) sagte er zu ihm: „Effata!“, das heißt: „Öffne dich!“',
        35: 'Und sofort öffneten sich seine Ohren (Hörgänge), und die Hemmung (Fessel) seiner Zunge löste sich, und er konnte richtig sprechen.',
        36: 'Und er schärfte [den Leuten] ein (ordnete an, verbot), mit niemandem zu sprechen. Aber je mehr er es ihnen einschärfte (verbot, darauf bestand), desto mehr machten (predigten, verkündeten) sie [es] bekannt.',
        37: 'Und sie waren zutiefst (maßlos) erstaunt (überwältigt, beeindruckt) und sagten: „Er hat alles gut gemacht, und er befähigt (macht, [dass]) die Tauben zu hören und die Stummen zu sprechen!“',
    },
    8: {
        1: 'Als in jenen Tagen wieder einmal eine große Menschenmenge [bei Jesus] war und [sie] nichts zu essen hatten, da rief er die Jünger zu sich und sagte zu ihnen:',
        2: '„Ich bedauere (habe Mitleid mit) die Menschenmenge (den Leuten), weil sie schon drei Tage lang bei mir sind und nichts zu essen haben.',
        3: 'Und wenn ich sie ohne zu essen (hungrig) nach Hause gehen lasse (schicke), dann werden sie unterwegs zusammenbrechen (sehr schwach werden). Und manche von ihnen sind von weit her (von so weit her) gekommen.“',
        4: "Und seine Jünger antworteten ihm: „Woher soll man [all] diese [Leute] ''hier'' in [dieser] Einöde (unbewohnten Gegend) mit Broten (Nahrung) satt machen können?“",
        5: 'Und er fragte sie: „Wie viele Brote habt ihr?“Sie {aber} sagten: „Sieben.“',
        6: 'Daraufhin (Und) gab er der Menschenmenge die Anweisung, auf dem Boden Platz zu nehmen; und nachdem er die sieben Brote genommen (erhalten) und ein Dankgebet gesprochen hatte, brach er sie durch und gab sie seinen Jüngern, um sie auszuteilen, und sie teilten sie an die Menschenmenge (Leute) aus.',
        7: 'Und sie hatten ein paar Fische (kleine Fische) dabei; und er segnete sie und ließ auch sie verteilen.',
        8: 'Und [die Menschen] aßen und wurden satt, und sie hoben die übrig gebliebenen Brocken auf, sieben Körbe.',
        9: 'Es waren {aber} etwa viertausend [Menschen]. Danach (Und) verabschiedete (ließ gehen, schickte weg) er sie,',
        10: 'und gleich darauf stieg er mit seinen Jüngern in das Boot und gelangte (kam) in das Gebiet von Dalmanuta.',
        11: 'Da (Und) kamen die Pharisäer zusammen (heraus) und begannen mit ihm zu streiten, wobei sie von ihm ein Zeichen vom Himmel verlangten, um (wobei sie) ihm eine Falle zu stellen (ihn auf die Probe zu stellen; zu testen).',
        12: 'Und er stöhnte (seufzte tief) aus dem Innersten (innerlich) auf und sagte: „Wie!? Diese Generation (Dieses Pack) verlangt ein Zeichen? (Warum verlangt diese Generation ein Zeichen?) Amen (Ja, Wahrlich), ich sage euch: Wenn dieser Generation (diesem Pack) ein Zeichen gegeben werden wird... (Nie und nimmer wird dieser Generation ein Zeichen gegeben werden)!“',
        13: 'Und er ließ sie [stehen] (verließ sie), stieg wieder ein und fuhr zum anderen Ufer.',
        14: '{Und} Sie hatten vergessen (vergaßen), Brote mitzunehmen, sodass (und) sie bis auf eines kein Brot im Boot dabei hatten.',
        15: 'Und er schärfte ihnen ein (warnte sie) {sagend}: „Passt auf (Seht zu), hütet euch vor dem Sauerteig der Pharisäer und vor dem Sauerteig von Herodes!“',
        16: 'Und sie diskutierten weiter (begannen zu diskutieren) miteinander (machten sich Gedanken) [darüber], dass (weil) sie keine Brote hatten.',
        17: 'Und Jesus, der (als er, weil er) Bescheid wusste ([das] bemerkte), sagte zu ihnen: „Warum diskutiert ihr (macht ihr euch Gedanken) [darüber], dass ihr keine Brote habt? Begreift und versteht ihr [denn immer] noch nicht? Habt ihr ein (euer) verstocktes (verhärtetes) Herz?',
        18: 'Ihr habt zwar Augen, aber seht nicht? Und ihr habt zwar Ohren, aber hört nicht? Und erinnert ihr euch nicht? (Und denkt daran:)',
        19: 'Als ich die fünf Brote für die fünftausend [Menschen] zerbrochen habe, wie viele große Körbe voller Brocken habt ihr aufgehoben?“Sie antworteten (sagten) ihm: „Zwölf.“',
        20: '„Und als [ich] die sieben [Brote] für die viertausend [Menschen] [zerbrochen habe], wie viele Körbe voller Brocken habt ihr aufgehoben?“Und sie antworteten (sagten) ihm: „Sieben.“',
        21: 'Da (und) sagte er (fuhr fort) zu ihnen: „Versteht ihr immer noch nicht?“',
        22: 'Als sie nach Betsaida kamen, ({Und} sie kamen nach Betsaida. {Und es}) brachten [die Leute] einen Blinden zu ihm und baten (forderten auf) [Jesus], ihn zu berühren.',
        23: 'Und er nahm die Hand des Blinden und führte ihn aus dem Dorf hinaus, und nachdem er ihm in die Augen gespuckt und ihm die Hände aufgelegt hatte, fragte er ihn: „Siehst du etwas?“',
        24: 'Und nachdem [der Mann] wieder sehen konnte ([der Mann] blickte auf und), sagte er: „Ich sehe die Leute (Menschen) – {dass} wie Bäume, ich sehe sie umhergehen.“',
        25: 'Daraufhin legte [Jesus] erneut die Hände auf seine Augen, und [der Mann] hatte klare Sicht (sah klar) und war wieder gesund (wiederhergestellt), und er konnte nun alles deutlich (scharf) erkennen.',
        26: 'Da (Und) schickte [Jesus] ihn nach Hause (in sein Haus), wobei er ihm auftrug (sagte): „Geh auch (aber) nicht ins Dorf! “',
        27: 'Und Jesus und seine Jünger zogen weiter (gingen fort, machten sich auf) in die Dörfer von Cäsarea Philippi; und auf dem Weg befragte er seine Jünger {und sagte zu ihnen}: „Für wen halten mich die Leute?“',
        28: 'Da sagten sie zu ihm {sagend}: „ [Einige für] Johannes den Täufer und andere [für] Elija, wieder andere [meinen], dass [du] einer von den Propheten [bist].“',
        29: 'Und er fragte sie: „Und ihr - für wen haltet ihr mich?“Und {antwortend} sagte Petrus zu ihm: „Du bist der Messias (Gesalbte; Christus)!“',
        30: 'Und er schärfte (befahl) ihnen ein, {damit} mit niemandem über ihn sprechen.',
        31: 'Und er begann sie darüber aufzuklären (zu lehren), dass der Menschensohn (Sohn des Menschen; Mensch) viel leiden, und von den Ältesten und den obersten (führenden, Hohen) Priestern und den Schriftgelehrten (Schreibern) abgelehnt (verworfen, zurückgewiesen) werden, und getötet werden und nach drei Tagen auferstehen müsse.',
        32: 'Und er sagte das ganz offen. Da (Und) nahm Petrus ihn beiseite und begann, missbilligend auf ihn einzureden (ihn zu rüffeln/zurechtzuweisen).',
        33: 'Der drehte sich um und – indem (und) er seine Jünger ansah (nachdem … angesehen hatte) – wies Petrus zurecht (herrschte ihn an) {und sagte}: „Geh hinter mich (Geh weg von mir), Satan (Widersacher)! denn Du hast nicht die [Vorstellungen (Interessen)] Gottes im Sinn, sondern die der Menschen.“',
        34: 'Dann (Und) rief er die Menschenmenge samt seinen Jüngern zu sich und sagte zu ihnen: „Wenn jemand mir nachfolgen will, dann muss (soll) er sich selbst verleugnen, {und} sein Kreuz tragen (auf sich nehmen, aufheben, mitnehmen) und mir nachfolgen!',
        35: 'Denn jeder, der (wer) sein Leben (Seele) retten will, wird es verlieren; aber jeder, der (wer) wegen mir und dem Evangelium (der Heilsbotschaft, um meinet- und des Evangeliums willen) sein Leben (Seele) verliert, wird es retten.',
        36: 'Denn was nützt es einem Menschen, die gesamte Welt zu gewinnen, aber (und [dabei]) sein Leben (Seele) zu verlieren?',
        37: 'Denn was könnte (sollte) man (ein Mensch) als Gegenwert für sein Leben (Seele) geben?',
        38: 'Denn jeder, der (wer immer) sich in dieser untreuen (ehebrecherischen) und sündigen Generation (jeder dieses untreuen und sündigen Packs, der sich) über (wegen) mich und meine Worte schämt, über den wird sich auch der Menschensohn (Sohn des Menschen; Mensch) schämen, sobald er in der Herrlichkeit seines Vaters mit den heiligen Engeln kommt.“',
    },
    9: {
        1: 'Und weiter sagte er zu ihnen: „Amen (Wahrlich, Ja), ich sage euch: Es gibt einige unter denen, die hier stehen, die den Tod nicht schmecken (nicht sterben) werden, bis (bevor, ehe) sie gesehen haben, wie Gottes Reich (Herrschaft) mit Macht (Kraft) gekommen ist. “',
        2: 'Sechs Tage später nahm Jesus Petrus, Jakobus und Johannes (die Brüder Jakobus und Johannes?), und führte sie für sich, allein, auf einen hohen Berg, und er wurde vor ihnen (vor ihren Augen) verwandelt (verwandelte sich):',
        3: '{und} Seine Obergewänder {wurden} strahlten [so] sehr (blendend) weiß, wie sie kein Walker auf der [ganzen] Erde {derart} weiß färben könnte.',
        4: 'Und es erschien ihnen Elija zusammen mit Mose, und sie sprachen ({waren im Gespräch}) mit Jesus.',
        5: 'Da {antwortete und} sprach Petrus zu Jesus: „Meister (Rabbi), es ist gut, dass wir hier sind! Und lass uns (so lass uns denn) drei Hütten (Zelte) bauen - dir eine, Mose eine und Elija eine!“',
        6: 'Er wusste nämlich nicht, wie er reagieren (was er antworten) sollte; denn (so sehr) sie fürchteten sich (waren in Furcht geraten).',
        7: 'Und eine Wolke {entstand und} hüllte (verbarg, überschattete) sie ein, und eine Stimme kam aus der Wolke: „Dies ist mein geliebter (einziger) Sohn, [darum] hört auf ihn!“',
        8: 'Und plötzlich, als sie sich umblickten, sahen sie niemanden {nicht} mehr bei sich als Jesus allein.',
        9: 'Während sie vom (aus dem) Berg herabstiegen, befahl er ihnen {damit}, niemandem zu erzählen, was sie gesehen hatten - erst (außer), wenn der Menschensohn von den Toten auferstanden sei.',
        10: 'Und sie behielten das Wort bei sich ({bei sich}), diskutierten (miteinander) aber, was dies sei - „von den Toten Auferstehen“.',
        11: 'Dann fragten sie ihn {und sagten}: „Warum sagen [dann] die Schriftgelehrten (fragten sie ihn, warum die Schriftgelehrten sagten), dass zuerst Elija kommen müsse?“',
        12: 'Und er sagte zu ihnen: „In der Tat (zwar) kommt Elija zuerst und stellt alles wieder her. Aber [gleichzeitig] steht (und wie/warum steht) über den Menschensohn geschrieben (?), dass (damit) er vieles leiden und verachtet werden müsse. (?)',
        13: 'Aber ich sage euch (Ja, mehr noch:), Elija ist auch (sogar) [bereits] gekommen, und sie haben mit ihm gemacht, was sie wollten - wie über ihn geschrieben steht.“',
        14: 'Und als sie (er) zu den Jüngern kamen (kam), sahen sie (sah er), dass eine große Menschenmenge um sie [war] und Schriftgelehrte mit ihnen diskutierten.',
        15: 'Und sofort, als die ganze Menschenmenge ihn sah, erschrak sie (staunte sie, geriet sie in Ehrfurcht), rannte auf ihn zu und begrüßte ihn [freudig].',
        16: 'Da fragte er sie: „Worüber (warum) diskutiert ihr mit ihnen?“',
        17: 'Einer aus (aus heraus) der Menschenmenge antwortete ihm: „Lehrer, ich habe meinen Sohn zu dir gebracht (wollte ihn zu dir bringen), weil er einen stummen Geist (einen Geist, der ihn stumm macht) hat (von einem stummen Geist besessen ist).',
        18: 'Und wo auch immer [er ist, wenn] er ihn anfällt (packt), zerrt er ihn hin und her (wirft er ihn zu Boden) und ihm tritt Schaum vor den Mund (er schäumt) er knirscht mit den Zähnen und er wird [ganz] starr. Und ich sagte zu deinen Jüngern, dass (damit) sie ihn vertreiben sollen (bat deine Jünger, ihn auszutreiben), und (aber) sie konnten es nicht (sie waren zu schwach dafür). “',
        19: 'Da {antwortete und} sagte er ihnen (fuhr er sie an): „Oh, [du] ungläubiges Geschlecht (Pack)! Bis wann (wie lange) werde (muss) ich [denn noch] bei euch sein? Bis wann werde (muss) ich euch [denn noch] ertragen? Bringt ihn zu mir!“',
        20: 'Sie brachten ihn zu ihm. Und als ihn der Geist sah (Kaum hatte der Geist ihn gesehen - da...), schüttelte er ihn sofort in [heftigen] Krämpfen, und die Erde gefallen wälzte er sich schäumend (so dass der Knabe sich mit Schaum vor dem Mund auf der Erde wälzte).',
        21: 'Da fragte er dessen Vater: „Wieviel Zeit ist es, seit [der] ihm dies passiert? (Wie lange geht das schon so mit ihm?) “Und er sagte: „ [Schon] von [frühester] Kindheit an.',
        22: 'Ja (und), mehrfach hat er ihn sogar (sowohl) ins Feuer oder (als auch) ins Wasser geworfen, um ihn umzubringen. Ich flehe dich an (aber), wenn du etwas vermagst (wenn etwas in deiner Macht steht), dann hilf uns und hab Mitleid mit uns (erbarme dich unser)! “',
        23: "Jesus antwortete ihm: {Das} „'Wenn du es vermagst (Wenn es in deiner Macht steht) '... - Wer glaubt, vermag ''alles'' (ist allmächtig)! “",
        24: 'Sofort (Da) schrie (schluchzte) der Vater des Jungen und sagte: „Ich glaube! Hilf meinem Unglauben!“',
        25: 'Als Jesus sah, dass eine Menschenmenge zusammenlief (herandrängte), gebot er dem unreinen Geist {und sagte zu ihm}: „Du stummer und tauber Geist, ich befehle dir, komm aus ihm heraus (fahre aus ihm aus) und geh nie mehr in ihn hinein (fahre nie mehr in ihn hinein)!“',
        26: 'Und schreiend und [den Jungen] in heftigen Krämpfen schüttelnd kam er heraus (fuhr der Geist aus). Und er wurde (war) wie tot, daher (sodass) die Meisten (die Menge) sagten, er sei gestorben.',
        27: 'Doch Jesus ergriff seine Hand und hieß ihn aufstehen (richtete ihn auf, weckte ihn auf, heilte ihn) - und er stand auf.',
        28: 'Und nachdem er ins Haus gegangen war, fragten ihn seine Jünger für sich: „Dass wir ihn nicht austreiben konnten (Warum konnten wir ihn nicht austreiben)?“',
        29: 'Da sagte er zu ihnen: „Diese Art kann durch nichts ausfahren (ausgetrieben werden) außer durch Gebet.“',
        30: 'Von dort aus (gingen sie fort und) reisten sie durch Galiläa, und er wollte nicht, dass (damit) jemand es erführe,',
        31: 'denn er lehrte (wollte lehren) seine Jünger und sagte zu ihnen: „Der Menschensohn ist in die Hände der Menschen ausgeliefert (wird ausgeliefert werden), und sie werden ihn töten, und nachdem (obwohl) er getötet worden ist, wird er nach drei Tagen auferstehen.“',
        32: 'Sie verstanden das Wort (diesen Ausspruch) jedoch nicht, und sie fürchteten sich, ihn zu fragen.',
        33: 'Sie kamen nach Kafarnaum. Als er im Haus war (ankam), fragte er sie: „Worüber (Was) habt ihr auf dem Weg (unterwegs) diskutiert (überlegt)?“',
        34: 'Sie aber schwiegen, denn sie hatten auf dem Weg (unterwegs) miteinander [darüber] diskutiert, wer der Größte (größer) [sei].',
        35: 'Da setzte er sich, rief (wandte sich an) die Zwölf und sagte zu ihnen: „Wenn jemand der Erste sein will, wird (muss) er der Letzte von Allen und der Diener von Allen sein.“',
        36: 'Und er nahm ein Kind, stellte es in ihre Mitte, umarmte es und sagte zu ihnen:',
        37: '„Wer eines von solchen Kindern (ein solches Kind) in meinem Namen (mir zuliebe, um meinetwillen) aufnimmt, nimmt mich auf, und wer mich aufnimmt, nimmt nicht mich auf, sondern (vielmehr) den, der mich gesandt hat.“',
        38: 'Johannes sagte zu ihm: „Lehrer, wir haben gesehen, wie jemand Dämonen austrieb mit deinem Namen (und dabei deinen Namen verwendete). Wir hinderten ihn daran (haben versucht, ihn daran hindern), weil er uns nicht folgt (nicht zu uns gehört). “',
        39: 'Jesus aber sagte: „Hindert ihn nicht [daran], denn es gibt niemanden, der Wunder mit meinem Namen wirkt und schnell schlecht von mir zu sprechen vermag (von mir sprechen kann).',
        40: 'Denn wer nicht gegen uns ist, ist für uns (steht über uns).“',
        41: '„ {Denn} Wer euch [auch nur] einen Becher Wasser zu trinken gibt, weil (im Namen, dass) ihr zu Christus gehört - Amen, ich sage euch - der wird seinen Lohn nicht verlieren (wird ihn bekommen).',
        42: 'Wer aber (und) [auch nur] einen dieser Kleinen (einen der Geringen), die an mich ({an mich}) glauben, ärgert (vom Glauben abbringt) - für den ist (wäre) es gut (besser), wenn ein Eselsmühlstein um seinen Hals gehängt und er ins Meer geworfen würde. “',
        43: '„ {Und} Wenn deine Hand dich zur Sünde verführen will (zur Sünde verführt, ärgert, vom Glauben abbringt), hau sie ab! [Denn] es ist gut (besser), dass du verstümmelt in das Leben eingehst, als die zwei Hände habend (mit beiden Händen) in die Gehenna (Hölle) einzugehen (geworfen zu werden): in das unauslöschliche Feuer,',
        44: 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.',
        45: 'Und wenn dein Fuß dich zur Sünde verführen will (zur Sünde verführt, ärgert, vom Glauben abbringt), dann hau ihn ab! [Denn] es ist gut (besser), dass du lahm in das Leben eingehst, als die zwei Füße habend (mit beiden Füßen) in die Gehenna (Hölle) geworfen zu werden,',
        46: 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.',
        47: 'Und wenn dein Auge dich zur Sünde verführen will (zur Sünde verführt, ärgert, vom Glauben abbringt), reiß es aus! [Denn] es ist gut (besser), dass du einäugig in das Reich Gottes eingehst, als zwei Augen habend (mit zwei Augen) in die Gehenna (Hölle) geworfen zu werden,',
        48: "'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt'.",
        49: '{Denn} (Denn) Jeder wird mit Feuer gesalzen werden.',
        50: 'Gut [ist] das Salz. Aber wenn das Salz unsalzig (salzlos, geschmacklos) geworden ist - womit werdet (wollt) ihr es würzen? Habt (teilt) Salz unter (in) euch, und haltet [so] untereinander Frieden!“',
    },
    10: {
        1: 'Und von dort brach (stand) er auf und zog (kam) in das Gebiet von Judäa und (und zwar) das [Land] jenseits des Jordans, und wieder einmal (erneut) liefen Menschenmengen bei ihm zusammen, und wie es seine Gewohnheit war, lehrte er sie auch diesmal (wieder).',
        2: 'Daraufhin (Und) kamen einige Pharisäer herbei und wollten von ihm wissen (erkundigten sich), ob es einem Mann erlaubt sei, sich von [seiner] Frau zu scheiden (wegzuschicken), um (wobei sie) ihm eine Falle zu stellen (ihn auf die Probe zu stellen; zu testen).',
        3: 'Er jedoch erwiderte {und sagte zu ihnen}: „Was hat euch Mose vorgeschrieben (geboten)?“',
        4: 'Und sie sagten: „Mose hat es zugelassen, [der Frau] einen Scheidungsbrief zu schreiben und [sich dann von ihr] zu scheiden (wegzuschicken).“',
        5: 'Aber Jesus sagte zu ihnen: „Angesichts (wegen, mit Rücksicht auf) eurer Sturheit (Herzenshärte) hat er euch dieses Gebot (Vorschrift) aufgeschrieben (gegeben).',
        6: 'Aber seit [dem] Beginn der Schöpfung »hat er sie männlich und weiblich gemacht.«',
        7: '»Aus diesem Grund wird ein Mann seinen Vater und seine Mutter verlassen, und er wird sich mit seiner Frau vereinen (zusammenschließen)',
        8: 'und die beiden (zwei) werden zu einem Fleisch (Körper) sein (werden) «, daher sind sie nicht länger zwei, sondern ein Fleisch (Körper).',
        9: 'Was Gott verbunden (vereinigt, zusammengefügt) hat, das soll (darf) darum ein ([der]) Mensch nicht trennen.“',
        10: 'Als (Und) sich die Jünger im Haus (zu Hause) bei ihm noch einmal (wieder) danach erkundigten (fragten),',
        11: 'da (und) sagte er zu ihnen: „Jeder, der (Wer immer) sich von seiner Frau scheidet und eine andere heiratet, bricht an ihr die Ehe,',
        12: 'und wenn sie sich von ihrem Mann geschieden hat und einen anderen heiratet, bricht sie die Ehe.“',
        13: 'Und [die Leute] versuchten, Kinder zu ihm zu bringen (brachten), um {er} sie zu berühren, aber die Jünger wiesen sie unfreundlich ab (schimpften sie).',
        14: 'Doch als Jesus [das] sah, wurde er ärgerlich (ungehalten) und sagte zu ihnen: „Lasst die Kinder zu mir kommen! Haltet sie nicht auf, denn solchen [wie ihnen] gehört Gottes Reich (Herrschaft).',
        15: 'Ja (Amen, Wahrlich), ich sage euch: Jeder, der (Wer immer) Gottes Reich (Herrschaft) nicht wie ein Kind annimmt, kommt bestimmt nicht hinein.“',
        16: 'Und er nahm sie in die Arme und segnete sie, indem er ihnen die Hände auflegte.',
        17: 'Und als er nach draußen auf die Straße kam (sich auf den Weg machte), kam einer angerannt und kniete sich vor ihm hin. Er fragte ihn: „Guter Lehrer, was muss (soll) ich tun, um {ich} ewiges Leben zu bekommen (Anteil am … zu erhalten; erben)?“',
        18: "Jesus aber sagte zu ihm: „Warum nennst du ''mich'' gut? Niemand ist gut außer einem: Gott.",
        19: 'Du kennst die Gebote: »Töte (morde) nicht, brich die Ehe nicht, stiehl nicht, mache keine Falschaussage; unterschlage (betrüge, enthalte vor, raube) nicht; ehre deinen Vater und deine Mutter.«',
        20: 'Der [Mann] {aber} entgegnete (sagte) {ihm}: »Lehrer, das alles habe ich seit meiner Jugend befolgt (beachtet).«',
        21: 'Jesus {aber} sah ihn an und gewann ihn lieb, und er sagte zu ihm: »Eins fehlt dir [noch]: Geh, verkaufe alles, was du hast, und gib [den Erlös] den Armen, dann (und) wirst du einen Schatz im Himmel haben. Und [dann] komm, folge mir nach!«',
        22: 'Doch der [Mann] war erschüttert (getroffen; enttäuscht) über diese Forderung (das Gesagte; Wort) und ging traurig davon, denn er besaß viele Güter.',
        23: 'Und Jesus schaute sich um und sagte zu seinen Jüngern (Schülern): »Wie schwer werden [es] die Wohlhabenden [haben], in Gottes Reich (Königsherrschaft) zu kommen!«',
        24: 'Die Jünger {aber} waren von seinen Worten überrascht (bestürzt, entgeistert). Doch Jesus sagte noch einmal zu ihnen: »Kinder, wie schwer ist es, in Gottes Reich (Königsherrschaft) zu kommen!',
        25: 'Es ist leichter [für] ein Kamel, durch das Nadelöhr zu kommen, als [für] einen Reichen, in Gottes Reich (Königsherrschaft) zu kommen.«',
        26: 'Da waren sie völlig entgeistert (außer sich, erstaunt, überwältigt) und sagten zu einander: »Wer kann dann gerettet werden?!?«',
        27: 'Jesus sah sie an und sagte: »Bei Menschen [ist es] unmöglich, aber nicht bei Gott: Denn bei Gott [ist] alles möglich.«',
        28: 'Petrus sagte zu ihm: »Du weißt (Siehe), wir haben alles verlassen und sind dir nachgefolgt (haben uns dir angeschlossen)!«',
        29: 'Jesus sagte: »Ja (Amen, Wahrlich), ich sage euch: Es gibt niemanden, der Haus (Haushalt), {oder} Brüder oder Schwestern, {oder} Mutter, {oder} Vater oder Kinder oder Felder wegen mir und wegen des Evangeliums (der Heilsbotschaft) zurückgelassen (verlassen) hat,',
        30: 'der nicht [das] Hundertfache [dafür] bekommen wird (bekommt): jetzt, in dieser Zeit, Häuser und Brüder, {und} Schwestern, {und} Mütter, {und} Kinder und Felder, [wenn auch] unter Verfolgungen, und im kommenden Zeitalter (Welt) ewiges Leben.',
        31: 'Und (Aber) viele Erste werden Letzte sein und die Letzten Erste.«',
        32: 'Sie {aber} waren auf dem Weg nach Jerusalem, und Jesus ging ihnen voran, und (da) [die Jünger (Leute)] wunderten sich darüber (wurden von Beklommenheit erfasst; erschraken), und (aber) die, die hinter ihm gingen (die ihm Folgenden, seine Nachfolger), bekamen Angst. Da (und) nahm er die Zwölf noch einmal beiseite und teilte ihnen mit, was mit ihm geschehen würde:',
        33: '»Wir gehen jetzt {hinauf} nach Jerusalem, dann wird der Menschensohn (Sohn des Menschen; Mensch) an die obersten (führenden, Hohen) Priester und die Schriftgelehrten (Schreibern) ausgeliefert werden, und sie werden ihn [zum] Tod verurteilen und ihn an die Heiden (Nichtjuden) ausliefern,',
        34: 'und sie werden ihn verspotten, und sie werden ihn anspucken, und sie werden ihn auspeitschen und töten, und nach drei Tagen wird er auferstehen.«',
        35: 'Und Jakobus und Johannes, die Söhne von Zebedäus, kamen auf ihn zu und sagten zu ihm: »Lehrer, wir wollen, dass du [für] uns tust, worum wir dich auch bitten werden.«',
        36: 'Da sagte er zu ihnen: »Was wollt ihr, dass ich [für] euch tun soll?«',
        37: 'Sie sagten zu ihm: »Gewähre uns, {dass wir} in deiner Herrlichkeit (Herrschaft, Ehre) einer an deiner rechten und einer an deiner linken [Seite] zu sitzen!«',
        38: "Da sagte Jesus zu ihnen: »Ihr wisst nicht, um was ihr [da] bittet! Könnt ihr den Becher (Kelch) trinken, den ''ich'' trinke, oder [mit] der Taufe getauft werden, mit der ''ich'' getauft werde?«",
        39: 'Sie aber sagten zu ihm: » [Das] können wir!« Jesus aber sprach zu ihnen: »Den Becher (Kelch), den ich trinke, werdet ihr trinken, und [mit] der Taufe, mit der ich getauft werde, werdet ihr getauft werden,',
        40: 'aber es ist nicht meine Sache (steht mir nicht zu), [euch] das Sitzen an meiner rechten oder linken [Seite] zu gewähren,, sondern [das Sitzen steht denjenigen zu], [für] die es vorgesehen (bestimmt, bereitet) ist.«',
        41: 'Und als die zehn [anderen Jünger das] hörten, waren sie wütend (ärgerten sie sich) auf Jakobus und Johannes.',
        42: 'Und (da) Jesus rief sie zu sich und sagte zu ihnen: »Ihr wisst, dass diejenigen, die als Regierende der Völker (nichtjüdischen Völker, Nichtjuden) angesehen sind (gelten), die Menschen beherrschen (unterdrücken), und [dass] ihre Großen (Mächtigen) die Menschen ihre Macht spüren lassen (ihre Macht über sie missbrauchen).',
        43: 'Aber so ist es bei euch nicht! Wer (Jeder, der) bei (unter) euch groß sein (werden) möchte, soll vielmehr euer Diener sein,',
        44: 'und wer (jeder, der) bei (unter) euch bedeutend (Erster) sein (werden) möchte, soll Sklave aller [anderen] sein.',
        45: 'Denn auch der Menschensohn (Sohn des Menschen; Mensch) ist nicht gekommen, um sich dienen zu lassen, sondern um zu dienen und sein Leben als Lösegeld anstelle (für) vieler zu geben.«',
        46: 'Und sie kamen nach Jericho. Und als er von Jericho aufbrach, [er] und seine Jünger und eine beachtliche (ansehnliche) Menschenmenge, saß der Sohn von Timäus, Bartimäus, ein blinder Bettler, am Straßenrand,',
        47: 'Und als er hörte, dass es Jesus der Nazarener war, fing er an zu schreien {und zu sagen}: »Sohn Davids, Jesus, hab Erbarmen mit mir!«',
        48: 'Und viele herrschten ihn an, {damit} still zu sein. Aber er schrie umso lauter (mehr): »Sohn Davids, hab Erbarmen mit mir!«',
        49: 'Da (und) blieb Jesus stehen (stand auf) und sagte: »Ruft ihn!« Und sie riefen den Blinden und sagten zu ihm: »Keine Angst! (Hab nur Mut!) Steh auf, er ruft dich!«',
        50: 'Da warf er seinen Mantel (Obergewand) ab, sprang auf und kam zu Jesus.',
        51: 'Und Jesus fragte ihn: »Was willst du, dass ich für dich tue?« Da sagte der Blinde zu ihm: »Rabbuni, dass ich sehen kann!«',
        52: 'Und Jesus sagte zu ihm: »Geh, dein Glaube hat dich geheilt (gerettet)!«, und er konnte augenblicklich sehen, und er folgte (schloss sich an) ihm auf dem Weg. “',
    },
    11: {
        1: 'Und als sie in die Nähe von Jerusalem kamen (näherten), nach Betfage und Betanien beim Ölberg, schickte er zwei seiner Jünger los.',
        2: 'Er sagte zu ihnen „Geht in das Dorf, das vor euch [liegt], und gleich, wenn ihr hineingeht, werdet ihr ein Eselsfohlen (Fohlen) angebunden finden, auf dem noch nie ein Mensch gesessen hat. Bindet es los und bringt es her!',
        3: 'Und falls euch jemand fragt: »Was macht ihr da (Warum macht ihr das)?«, [dann] sagt: »Der Herr braucht es und schickt es [später] wieder zurück (hierher).«“',
        4: 'Daraufhin (Und) gingen sie los und fanden das Eselsfohlen (Fohlen), das draußen auf der Straße an eine Tür (Tor) gebunden war, und (als) sie banden es los.',
        5: 'Und (da) einige von den [Leuten], die dort herumstanden, fragten sie: „Was macht ihr [da], dass ihr das Eselsfohlen (Fohlen) losbindet?“',
        6: 'Da sagten sie ihnen genau [das, was] Jesus gesagt hatte, und [die Leute] ließen sie machen.',
        7: 'Und sie führten das Eselsfohlen (Fohlen) zu Jesus und legten ihre Kleider (Mäntel, Obergewänder) über [das Tier], und er setzte sich darauf.',
        8: 'Und viele breiteten ihre Kleider (Mäntel, Obergewänder) auf dem Weg aus, andere {aber} Zweige (lange Gräser, Laubbüschel), die sie auf den Feldern abgeschnitten (abgerissen) hatten.',
        9: 'Und die [Menschen], die vor [ihm] hergingen und [ihm] folgten, riefen immer wieder: „Hosanna! Gepriesen (Gesegnet) [sei], der im Namen des Herrn kommt!',
        10: 'Gepriesen (Gesegnet) [sei] das kommende Reich (Herrschaft) unseres Vaters (Vorfahren) David! Hosanna in den höchsten [Höhen]!“',
        11: 'So (Danach, Und) zog (ging) er hinein nach Jerusalem, in den Tempel (Tempelbezirk). Dann (Und), nachdem er sich alles angesehen hatte, begab sich mit den Zwölf nach Betanien, weil (als) die Stunde schon spät war.',
        12: '{Und} Als sie am folgenden Tag Betanien verließen, wurde er hungrig.',
        13: 'Und als er von weitem einen Feigenbaum mit Blättern sah, er ging hin, [um zu sehen], ob er vielleicht etwas daran fände. Doch (Und) als er hinkam, fand er nur (nichts außer) Blätter, es war nämlich nicht die Zeit für Feigen.',
        14: 'Da (Und) sagte er zu [dem Baum]: „Nie mehr, bis in Ewigkeit, soll jemand von dir Frucht essen!“Und seine Jünger hörten das.',
        15: 'Als (Und) sie nach Jerusalem kamen, {und} ging er in den Tempel (Tempelbezirk) und fing an, [alle], die im Tempel verkauften und kauften, hinauszutreiben. {und} Er warf die Tische der Geldwechsler und die Stände (Sitze) der Taubenverkäufer um',
        16: 'und ließ nicht zu, dass irgendjemand einen Gegenstand (etwas) durch den Tempelhof (Tempel) trug.',
        17: 'Dabei lehrte er sie: „Heißt es nicht (Steht nicht geschrieben): »Mein Haus wird ein Haus des Gebets für alle Völker (Nichtjuden) genannt werden«? Ihr aber habt daraus eine Räuberhöhle gemacht!“',
        18: 'Als (Und) die obersten (führenden, Hohen) Priester und die Schriftgelehrten (Schreiber) [davon (das)] hörten, {und} suchten sie [nach einer Möglichkeit], wie sie ihn aus dem Weg räumen (umbringen, beseitigen, loswerden) [könnten]. Sie fürchteten ihn nämlich, denn das ganze Volk war von seiner Lehre fasziniert (beeindruckt).',
        19: 'Und als es Abend (spät) wurde, gingen sie aus der Stadt hinaus.',
        20: 'Und als sie morgens [daran] vorbeikamen, sahen sie, dass der Feigenbaum von den Wurzeln her verdorrt war.',
        21: 'Und Petrus erinnerte sich und sagte (rief) zu ihm: „Rabbi, schau, der Feigenbaum, den du verflucht hast, ist verdorrt!“',
        22: 'Und Jesus entgegnete {und sagte zu ihnen}: „Habt Glauben (Vertrauen) [an] Gott!',
        23: 'Ja, (Amen, Wahrlich) ich sage euch: »Jeder, der (Wer) zu diesem Berg hier sagt: »Erhebe dich und stürze dich ins Meer!«, und in seinem Herzen nicht zweifelt, sondern glaubt (vertraut), dass geschieht, was er sagt, für den wird es eintreffen!',
        24: 'Daher sage ich euch: Glaubt (Vertraut) [bei] allen [Dingen], für die ihr betet und bittet, dass ihr [sie schon] erhalten habt, dann werden sie {für euch} eintreffen.',
        25: 'Und immer wenn ihr dasteht und betet (zum Beten steht), [dann] vergebt [den betreffenden Menschen], wenn ihr etwas gegen jemanden habt, damit auch euer Vater im Himmel euch eure Verfehlungen vergibt.',
        26: 'Doch wenn ihr nicht vergebt, dann wird auch euer Vater im Himmel eure Verfehlungen nicht vergeben. «',
        27: 'Und sie kamen wieder nach Jerusalem. Und während er sich im Tempel aufhielt (durch den Tempel ging), kamen die obersten (führenden, Hohen) Priester, {und} die Schriftgelehrten (Schreiber) und die Ältesten auf ihn zu',
        28: 'und fragen ihn: »Mit welchem Recht (Befugnis, Vollmacht, Autorität) tust du so etwas (diese [Dinge])? Oder wer hat dir dieses Recht (Befugnis, Vollmacht, Autorität) dazu gegeben, so etwas (solche [Dinge]) zu tun?«',
        29: 'Doch Jesus sagte zu ihnen: »Eines möchte ich von euch wissen. {und} Antwortet mir, dann (und) werde ich euch sagen, mit welchem Recht (Befugnis, Vollmacht, Autorität) ich so handle (so etwas; diese [Dinge] tue).',
        30: 'Die Taufe von Johannes – stammte (war) sie vom Himmel oder von Menschen? Sagt es (Antwortet) mir!«',
        31: 'Da (Und) besprachen sie sich (dachten bei sich) {und sagten}: »Wenn wir sagen: »vom Himmel«, wird er sagen: »Weshalb habt ihr ihm dann nicht geglaubt?«',
        32: 'Sagen wir aber (Sollen wir stattdessen sagen): »von Menschen«...?« Sie fürchteten das Volk (die Menschenmenge), denn alle waren der Meinung, dass Johannes tatsächlich ein Prophet gewesen war.',
        33: 'Also (Und) antworteten sie Jesus {und sagten}: »Wir wissen [es] nicht.« Da (Und) erwiderte (sagte) Jesus {zu ihnen}: »Dann sage ich euch auch nicht, mit welchem Recht (Befugnis, Vollmacht, Autorität) ich so handle (so etwas; diese [Dinge] tue).« “',
    },
    12: {
        1: 'Und er begann, mithilfe von (in) Gleichnissen (bildhaften Vergleichen) mit ihnen zu reden: „Ein Mann legte (pflanzte) einen Weinberg an, {und} er errichtete eine Mauer um ihn herum, {und} hob ein Auffangbecken (Keltertrog) [für die Weinpresse] aus und baute einen Wachtturm. Dann (und) verpachtete er ihn an Weingärtner (Bauern) und verreiste.',
        2: 'Und zur [vereinbarten] Zeit sandte er einen Sklaven (Knecht) zu den Weingärtnern (Bauern), um von den Weingärtnern (Bauern) [seinen Anteil] an den Erträgen (Früchten) des Weinbergs zu erhalten (abzuholen),',
        3: 'doch sie packten und schlugen (misshandelten, drangsalierten) ihn und schickten ihn mit leeren Händen [fort].',
        4: 'Da (Und) sandte er noch einen Sklaven (Knecht) zu ihnen. Auch den schlugen sie auf den Kopf (schändeten/verwundeten sie am Kopf) und entehrten ihn (behandelten ihn verächtlich).',
        5: 'Da (Und) sandte er einen weiteren, und den brachten sie um, und viele andere – manche verprügelten sie, andere brachten sie um.',
        6: 'Er hatte noch einen: [seinen] (noch [seinen] einzigen) geliebten Sohn. Er sandte ihn als letzten zu ihnen, weil er glaubte (dachte, sich sagte): »Meinen Sohn werden sie respektieren (achten).«',
        7: 'Aber jene Weingärtner (Bauern) sagten zueinander: »Das ist der Erbe! Kommt, wir bringen ihn um, dann wird das Erbe uns gehören!«',
        8: 'Und sie packten ihn und brachten ihn um, danach (und) warfen sie ihn hinaus vor den Weinberg.',
        9: 'Was wird nun der Besitzer (Herr) des Weinbergs tun? Er wird kommen und die Weingärtner (Bauern) ausmerzen (töten, vernichten), und den Weinberg wird er anderen geben.',
        10: "Habt ihr nicht auch (nicht einmal) diese Schriftstelle gelesen? » [Der] Stein, den die Bauleute abgelehnt (verworfen, zurückgewiesen) haben, ''der'' ist zum Schlussstein (Kopfstein, Eckstein) geworden;",
        11: 'Das kommt vom Herrn, und es ist wunderbar (erstaunlich, verwunderlich) in unseren Augen.«“',
        12: 'Da (Und) wollten sie ihn gerne (suchten sie [nach einer Möglichkeit], ihn...) festnehmen (verhaften), aber sie fürchteten die Menschenmenge, denn sie wussten (merkten), dass er das Gleichnis gegen sie gesprochen hatte. Daher (und) sie ließen ihn zurück (ihn unbehelligt; von ihm ab) und gingen davon.',
        13: 'Und (danach) sie schickten einige Pharisäer und Herodianer (Anhänger von Herodes) zu ihm, um {sie} ihn [in] einer Äußerung ([mit] einer Frage) zu fangen (ertappen).',
        14: 'Und als sie ankamen, sagten sie zu ihm: „Lehrer, wir wissen, dass du objektiv (aufrichtig) bist und auf niemanden besondere Rücksicht nimmst: Du schaust {eben} nicht auf [das] Äußere [der] Menschen, sondern lehrst wirklich den Weg Gottes. Darf man [dem] Kaiser (Cäsar) Steuern zahlen oder nicht? Sollen wir [sie] zahlen oder nicht zahlen?“',
        15: 'Doch er erkannte ihre Heuchelei und sagte zu ihnen: „Warum stellt ihr mir eine Falle (versucht ihr mich)? Bringt mir einen Denar, damit ich [ihn] mir anschauen [kann].“',
        16: 'Da brachten sie [ihm einen]. Und er sagte zu ihnen: „Wessen Bild und Aufschrift [ist das hier]?“Sie {aber} antworteten (sagten) {ihm}: „ [Des] Kaisers (Cäsars).“',
        17: 'Da sagte Jesus zu ihnen: „Was [dem] Kaiser (Cäsar) gehört, gebt [dem] Kaiser (Cäsar) zurück, und was Gott [gehört], [gebt] Gott!“Da (Und) waren sie sehr erstaunt über ihn.',
        18: '{Und} es kamen zu ihm Sadduzäer, welche sagen (der Meinung sind), dass es keine Auferstehung gibt, und fragten ihn {sagend}:',
        19: '„Lehrer, Mose hat uns geschrieben: »Wenn jemandes Bruder stirbt, und eine Frau zurücklässt und kein Kind hinterlässt, dass dann sein Bruder dessen Frau nehmen und er für seinen Bruder Nachkommen (Samen) zeugen (aufrichten) soll«.',
        20: 'Es waren [einmal] sieben Brüder. Und der erste nahm eine Frau, und als er starb, hinterließ er keinen Nachkommen (Samen).',
        21: 'Und der zweite nahm sie, und er starb und hinterließ keinen Nachkommen (Samen). Und der dritte ebenso.',
        22: '{Und} die Sieben hinterließen [also alle] keinen Nachkommen. [Als] Letzte von allen starb auch die Frau.',
        23: 'Bei der Auferstehung, wenn sie auferstehen:Wessen Frau von diesen wird sie sein? Denn die sieben hatten sie [alle] zur Frau.“',
        24: 'Jesus sagte zu ihnen: „Täuscht ihr euch nicht deshalb, weil ihr die Schriften nicht kennt und nicht Gottes Kraft?',
        25: 'Denn wenn sie von den Toten auferstehen, werden sie weder heiraten noch werden sie verheiratet, sondern sie sind wie Engel im Himmel (in den Himmeln).',
        26: 'Hinsichtlich der Toten aber, dass sie auferweckt werden – habt ihr nicht im Buch des Mose über den Dornbusch gelesen, wie Gott [da] zu ihm sprach {sagend}: »Ich [bin] der Gott Abrahams und der Gott Isaaks und der Gott Jakobs«?',
        27: 'Er ist nicht ein Gott der Toten, sondern der Lebenden. Ihr täuscht euch sehr.“',
        28: 'Und es kam einer von den Schriftgelehrten zu ihnen, der gehört hatte, wie sie diskutierten (ihre Diskussion, ihr Streiten). Und als er sah, dass er ihnen gut geantwortet hatte, fragte er ihn: „Was ist das höchste (erste) Gebot von allen?“',
        29: 'Jesus antwortete: „Das höchste (erste) Gebot ist: »Höre Israel: Der Herr, unser Gott, ist Herr allein,',
        30: 'und liebe (du sollst lieben) den Herrn, deinen Gott, aus deinem ganzen Herzen und aus deiner ganzen Seele und aus deinem ganzen Verstand (Vernunft, Gesinnung) und aus deiner ganzen Kraft (Macht, Stärke).«',
        31: 'Das zweite (andere) ist dieses: »Liebe (und du sollst lieben) deinen Mitmenschen (Nächsten, Nahestehenden, Nachbarn) wie dich selbst!« Größer als diese ist kein anderes Gebot.“',
        32: 'Und der Schriftgelehrte sagte zu ihm: „Gut, Lehrer, hast du von der Wahrheit geredet: »Er nur einer ist und kein (nicht ein) anderer außer ihm.«',
        33: 'Und »ihn zu lieben aus ganzem Herzen und aus ganzer Auffassungsgabe und aus ganzer Kraft und den Mitmenschen (Nächsten, Nahestehenden, Nachbarn) zu lieben wie sich selbst«, ist mehr als alle Brandopfer und Schlachtopfer.“',
        34: 'Als Jesus sah, dass er verständig antwortete, sagte er zu ihm: „Du bist nicht weit [entfernt] vom Reich Gottes (von der Gottesherrschaft).“Und niemand wagte mehr, ihn zu fragen.',
        35: '{Und} Jesus sprach (antwortete) {und redete}, als er im Tempel lehrte: „Wie [können] die Schriftgelehrten sagen, dass der Gesalbte der Sohn Davids ist?',
        36: 'David selbst sagte im heiligen Geist: »Der Herr sagte zu meinem Herrn. Setze [dich] zu meiner Rechten, bis ich deine Feinde unter deine Füße setze.«',
        37: 'David selbst nennt ihn Herrn, und wie soll er [dann] Sohn sein?“Und die große Menschenmenge hörte ihn gern.',
        38: 'Und er sagte in seiner Lehre: „Hütet euch vor den Schriftgelehrten, die in Roben umhergehen wollen und Begrüßungen auf den Marktplätzen',
        39: 'und Vorsitze in den Synagogen und erste Plätze bei den Festmählern [begehren].',
        40: 'Diejenigen, die die Häuser der Witwen verschlingen und für den Anschein lange beten, sie werden ein umfangreicheres Urteil erhalten.“',
        41: 'Und er setzte sich gegenüber dem Opferkasten und beobachtete, wie die Menschenmenge Geld in den Opferkasten warf; und viele Reiche warfen viel ein.',
        42: 'Da kam eine einzige arme Witwe und warf zwei Lepta ein, das entspricht einem Quadrans.',
        43: 'Und nachdem er seine Jünger zu sich gerufen hatte, sagte er zu ihnen: „Amen, ich sage euch: Diese arme Witwe hat mehr als alle [anderen] eingeworfen, die [etwas] in den Opferkasten eingeworfen haben.',
        44: 'Denn alle haben [etwas] aus ihrem Überfluss eingeworfen, sie aber hat aus ihrem Mangel alles, was sie hatte, eingeworfen – ihr ganzes Leben (ihren ganzen Lebensunterhalt).“',
    },
    13: {
        1: '{Und} (Und) als er aus dem Tempel hinausging (hinausgeht), sagte (sagt) einer seiner Jünger zu ihm: „Lehrer! {Sieh nur!} (Sieh nur!) Was für Steine und was für Gebäude!“',
        2: 'Da (Und) sagte Jesus zu ihm: „Du achtest auf diese großen Gebäude? (Diese Gebäude da?, Siehst/bewunderst du diese großen Gebäude?, Du siehst/bewunderst diese großen Gebäude.) Nicht (Keinesfalls) wird [hier] gelassen werden Stein auf Stein, der nicht {sicher} (sicher) zerstört (herausgebrochen) werden wird.“',
        3: 'Als er dann saß (sich setzte) auf dem (den) Ölberg gegenüber dem Tempel, fragte [n] ihn Petrus, Jakobus, Johannes und Andreas alleine:',
        4: '„ {Sag uns:} Wann wird dies sein? Und was [wird sein] das Zeichen [dafür], wann dies alles bestimmt ist (im Begriff ist), zu geschehen (vollendet zu werden, zu enden)?“',
        5: 'Und Jesus sagte zu ihnen ({begann}, zu ihnen zu sagen): „Habt acht (seht zu), dass euch niemand irreführt!',
        6: '[Denn] es werden viele unter meinem Namen kommen und sagen: »Ich bin [es]!«, und sie werden viele irreführen.',
        7: 'Wenn ihr {aber} (Ihr dagegen: Wenn ihr) von Kriegen und Kriegsgerüchten hört, erschreckt nicht, [denn] es muss geschehen, doch [es ist] noch nicht das Ende.',
        8: 'Erheben wird sich nämlich (denn) Volk gegen Volk und Reich gegen Reich, Erdbeben werden sein stellenweise (mancherorts), geben wird es Hungersnöte. [Der] Anfang der Wehen [ist] dies.',
        9: 'Nehmt euch in Acht (Blickt auf euch selbst)! Man wird euch (sie werden) ausliefern an Synhedrien und Synagogen, ihr werdet geprügelt werden und ihr werdet meinetwegen vor Statthalter und Könige gestellt werden, ihnen zum Zeugnis -',
        10: 'denn (und, aber) zuerst muss das Evangelium bei ({bei}) allen Völkern verkündigt werden.',
        11: 'Und wenn man euch abführt (sie euch abführen), um euch auszuliefern, sorgt euch nicht im Voraus, was ihr sagen sollt, sondern das, was (was auch immer) euch in jener Stunde eingegeben (gegeben) werden wird, das sagt! Denn nicht ihr seid es, die da reden, sondern der heilige Geist.',
        12: '{Und} Ausliefern wird ein Bruder [seinen] Bruder in den Tod und ein Vater [sein] Kind, und erheben werden sich Kinder gegen [ihre] Eltern und töten werden sie sie.',
        13: 'Und ihr werdet von allen gehasst werden wegen meines Namens (um meinetwillen, wegen mir). Der aber, der bis zum Ende standhaft bleibt (dies erduldet), wird gerettet werden.',
        14: 'Wenn ihr dann aber den Gräuel der Verwüstung stehen seht, wo er nicht [stehen] soll – der Leser sei aufmerksam! –, dann sollen die in Judäa in die Berge fliehen;',
        15: 'wer auf dem Dach [ist], soll nicht ({weder}) hinabsteigen, um ({noch}) hineinzugehen (hineingehen), um etwas aus seinem Haus zu holen;',
        16: 'und wer auf dem Feld ist, soll nicht zurückkehren, um sein Obergewand zu holen.',
        17: '{Aber} Wehe denen, die in jenen Tagen schwanger sind oder stillen!',
        18: '{Aber} (Darum) Betet, dass es nicht während des Winters geschieht!',
        19: 'Denn es werden sein jene Tage eine derartige Bedrängnis, wie sie seit Beginn der Schöpfung, die Gott geschaffen hat, bis jetzt nicht geschehen ist und niemals geschehen wird.',
        20: '{Und} Wenn der Herr nicht die Tage verkürzt hätte, würde absolut niemand gerettet werden, doch um der Auserwählten willen, die er auserwählt hat, hat er die Tage verkürzt.',
        21: '{Und} Sagt dann einer zu euch: » {Siehe} Hier [ist] der Christus!« oder {Siehe} dort [ist er]! - glaubt [es] nicht,',
        22: 'denn aufstehen werden falsche Christusse und falsche Propheten, und darbieten werden sie Zeichen und Wunder, um – wenn möglich – die Auserwählten zu verführen (irrezuführen).',
        23: '{Ihr aber} (Ihr dagegen) seid achtsam! Ich habe euch alles vorausgesagt.',
        24: '{Aber} in jenen Tagen, nach jener Bedrängnis, wird die Sonne verdunkelt werden (sich verfinstern), {und} der Mond wird seinen Schein nicht geben,',
        25: '{und} die Stern werden vom Himmel fallen und die Kräfte in den Himmeln (am Himmel) werden erschüttert werden.',
        26: 'Und dann wird erscheinen (wird man sehen, werden sie sehen) den in den Wolken kommenden Menschensohn, mit großer Macht und Herrlichkeit.',
        27: 'Und dann wird er die Engel aussenden und die Auserwählten aus den vier Himmelsrichtungen (Winden) vom Ende der Erde bis zum Ende des Himmels sammeln.',
        28: 'Über den Feigenbaum {aber} lernt (erfahrt) ein Gleichnis: Sobald seine Zweige weich werden und Blätter treiben, wisst ihr, dass der Sommer nahe [ist].',
        29: 'So auch ihr: wenn ihr dies geschehen seht, erkennt, dass er (es) nahe vor den Toren (vor der Tür) ist!',
        30: 'Amen, ich sage euch: Nicht (Keinesfalls) wird diese Generation (Geschlecht) vergehen, bis dies alles geschehen sein wird.',
        31: 'Der Himmel und die Erde werden vergehen, meine Worte aber werden nicht vergehen.',
        32: 'Von dem Tag und der Stunde weiß niemand, weder die Engel (Boten) im Himmel, noch der Sohn, allein der Vater.',
        33: 'Seid achtsam! Seid wachsam! - denn ihr wisst nicht, wann der Zeitpunkt (da) ist.',
        34: '[Es ist] wie bei einem Mensch auf Reisen, der, als er das Haus verließ und seinen Knechten die Vollmacht gab (ihre Verantwortungen übertrug) - jedem seine [eigene] Aufgabe - {dabei} dem Torhüter gebot, dass er wachsam sei (Wache halte).',
        35: 'Seid also wachsam, denn ihr wisst nicht, wann der Herr des Hauses kommt - ob am Abend, zur Mitternacht, zum Hahnenschrei oder im Morgengrauen -',
        36: 'damit er, wenn er plötzlich kommt, euch nicht schlafend vorfindet.',
        37: 'Was ich {aber} euch sage, sage ich allen: Seid wachsam!“',
    },
    14: {
        1: 'Das Pascha-Fest und [das Fest der] ungesäuerten Brote waren {aber} in zwei Tagen. Da suchten die Hohepriester und die Schriftgelehrten [einen Weg], wie sie ihn mit einer List ergreifen und töten könnten,',
        2: 'denn sie sagten (sagten sich): „Nicht während des Festes, sonst wird es einen Aufruhr der Volksgemeinde geben.“',
        3: 'Und als er in Bethanien im Haus Simons des Leprakranken war – als er [bei Tisch] lag – kam eine Frau, die ein Alabastergefäß voll kostbaren, reinem Nardenparfums [bei sich] hatte. Nachdem sie das Alabastergefäß zerbrochen hatte, goss sie [das Öl] herab auf seinen Kopf.',
        4: 'Einige aber waren {untereinander} verärgert (voller Empörung) [und sagten] zueinander: „Für was ist diese Verschwendung des Parfums geschehen?',
        5: 'Man hätte nämlich dieses Parfum für mehr als 300 Denare (teurer als für 300 Denare) verkaufen und [den Erlös] den Armen geben können.“Und sie machten ihr Vorwürfe.',
        6: 'Jesus aber sprach: „Lasst sie! Was macht ihr ihr Beschwerden? Sie hat ein gutes Werk an mir getan –',
        7: 'und die Armen habt ihr immer bei euch und sooft (falls) ihr wollt, könnt ihr ihnen (immer) wohltun (Gutes tun); mich aber habt ihr nicht immer.',
        8: 'Was sie [tun] konnte (was sie hatte), hat sie getan: Sie hat es vorweggenommen, meinen Leib für das Begräbnis einzubalsamieren.',
        9: 'Amen, ich sage euch, wo auch immer diese Freuden-Botschaft (dieses Evangelium) auf der ganzen Welt verkündet wird, wird auch von dem, was diese getan hat, gesprochen werden – zur Erinnerung an sie.“',
        10: 'Und Judas Iskariot, einer der Zwölf, ging zu den Hohepriestern, um ihn an sie auszuliefern.',
        11: 'Und sie freuten sich, als sie [das] hörten, und versprachen, ihm Geld zu geben. Und er suchte [einen Weg], wie er ihn zur rechten Zeit ausliefern könnte.',
        12: 'Und am ersten Tag [des Festes] der ungesäuerten [Brote], als sie das Pascha [lamm] opferten (an dem man das Pascha [lamm] zu opfern pflegte), fragten ihn seine Jünger: „Wo willst du, [dass] wir {fortgehend} vorbereiten, damit du das Pascha essen kann?“',
        13: 'Und er sandte zwei seiner Jünger und sagte zu ihnen: „Geht in die Stadt, und es wird ein Mann auf euch zutreten, der einen Krug Wasser trägt. Folgt ihm,',
        14: 'und wo auch immer er hineingeht, sagt zu dem Hausherrn {dass}: »Der Lehrer sagt: »Wo ist mein Gästezimmer, wo ich das Pascha [mahl] mit meinen Jüngern essen kann?««!',
        15: 'Und dieser wird euch ein großes Zimmer im Obergeschoss zeigen, möbliert und vorbereitet. Dort bereitet für uns vor!“',
        16: 'Und die Jünger gingen hinaus und kamen in die Stadt, und sie fanden [alles so] vor, wie er [es] ihnen gesagt hatte, und sie bereiteten das Pascha [mahl] vor.',
        17: 'Und als [es] Abend geworden war (wurde), kam er mit den Zwölf.',
        18: 'Und während (als) sie zum Essen lagen, sagte Jesus: „Amen, ich sage euch: Einer von euch, der mit mir isst, wird mich ausliefern.“',
        19: 'Das machte sie bestürzt (traurig) und einer nach dem anderen sagte zu ihm: „Doch nicht etwa ich?“',
        20: 'Da sagte er zu ihnen: „Einer der Zwölf, der [das Brot] mit mir in die (eine) Schüssel tunkt.',
        21: 'Denn der Menschensohn geht zwar, wie über ihn geschrieben steht, aber wehe jenem Menschen, durch den der Menschensohn ausgeliefert wird! [Es wäre] besser für ihn, wenn jener Mensch nicht geboren worden wäre.“',
        22: 'Und als er bei (nach) ihrem Essen ein Brot genommen und [Gott] gedankt hatte, hatte, brach er [es], gab [es] ihnen und sagte: „Nehmt, dies ist mein Leib!“',
        23: 'Und als er einen Becher (Kelch) genommen und [Gott] gedankt hatte, gab er [ihn] ihnen und sie alle tranken aus diesem.',
        24: 'Und er sagte zu ihnen: „Dies ist mein Blut des (neuen) Bundes, für viele vergossen.',
        25: 'Amen, ich sage euch: Ich werde nicht wieder vom Gewächs des Weinstocks trinken bis zu jenem Tag, an dem ich [von] ihm erneut (ihn als neuen) im Reich Gottes trinken werde.“',
        26: 'Und nachdem sie [Loblieder] gesungen hatten, gingen sie hinaus zum Ölberg.',
        27: 'Da sagt [e] Jesus zu ihnen: „Ihr werdet alle zu Fall kommen (ärgern),,weil geschrieben steht: »Ich werde den Hirten schlagen (erschlagen), und die Schafe werden zerstreut werden.«',
        28: 'Doch nachdem ich auferweckt worden sein werde, werde ich euch nach Galiläa vorausgehen (in Galiläa anführen).“',
        29: 'Petrus aber sagte zu ihm: „Und wenn alle zu Fall kommen (sich ärgern) werden – ich aber nicht!“',
        30: 'Und Jesus sagt [e] zu ihm: „Amen, ich sage dir: Du wirst mich heute, in dieser Nacht, vor dem zweimaligen Krähen des Hahns, dreimal verleugnen.“',
        31: 'Er aber sagte [überaus] vehement: „Wenn ich zusammen sterben müsste mit dir, werde ich dich keinesfalls verleugnen!“Und genauso redeten auch alle [anderen].',
        32: 'Und sie kommen (kamen) zu einem Grundstück (Landstück), dessen Name „Getsemani“[war], und er sagt [e] seinen Jüngern: „Setzt euch (sitzt) hier, bis ich gebetet habe!“',
        33: 'Dann nimmt (nahm) er Petrus und Jakobus und Johannes mit sich und begann, erschreckt (erstaunt) und verängstigt zu sein (war erschreckt und verängstigt),',
        34: 'und er sagt [e] ihnen: „Meine Seele ist (ich bin) zu Tode betrübt; bleibt hier und wacht (bleibt wach)!“',
        35: 'Und nachdem er ein wenig weitergegangen war, warf er sich (fiel er) auf die Erde und betete, dass – wenn es möglich sei – die Stunde an ihm vorüberginge,',
        36: 'und er sagte: „Abba, Vater, alles [ist] dir möglich. Trag diesen Becher (Kelch) an mir vorüber! Doch nicht, wie ich will, sondern wie du [willst]!“',
        37: 'Und er kommt (kam) und findet (fand) sie schlafend [vor] und er sagt [e] zu Petrus: „Simon, du schläfst!? (Schläfst du?) Vermochtest du nicht eine einzige Stunde zu wachen!?',
        38: 'Seid wach (wachsam) und betet darum, dass (damit) ihr nicht in Versuchung geratet! Der Geist [ist] zwar willig, aber das Fleisch [ist] schwach.“',
        39: 'Und nachdem er erneut weggegangen war, betete und sprach dasselbe Gebet (Wort).',
        40: 'Und nachdem er zurückkehrte, fand er sie erneut schlafend [vor], denn ihre Augen waren schwer. Und sie wussten nicht, was sie ihm antworten sollten.',
        41: 'Und er kommt (kam) das dritte Mal und sagt [e] ihnen: „Von nun an könnt ihr schlafen und euch ausruhen, es langt. Die Stunde ist gekommen, siehe!, ausgeliefert wird der Menschensohn in die Hände der Sünder.',
        42: 'Erhebt euch, lasst uns aufbrechen! Siehe!, der mich ausliefert, ist genaht.“',
        43: 'Und sogleich, noch während er redete, kommt (kam) Judas, einer der Zwölf, und mit ihm eine Menge mit Schwertern und Keulen (Schlagstöcken) von den Hohepriestern und den Schriftgelehrten und den Ältesten.',
        44: 'Aber der ihn auslieferte, hatte ihnen ein Signal gegeben (ein Signal mit ihnen vereinbart) {, sagend}: „Den, welchen ich küssen (lieben) werde, der ist es. Ergreift ihn und führt ihn gesichert (unter Bewachung, sicher) ab!“',
        45: 'Und als er kam [und] sogleich zu ihm kam, sagt [e] er: „Rabbi! (Rabbi, Rabbi!) “,, und er küsste ihn.',
        46: 'Da legten sie (sie aber legten) die Hände an ihn und ergriffen ihn (nahmen ihn fest).',
        47: 'Ein Gewisser aber von den Dabeistehenden zog das Schwert, schlug den Diener des Hohepriesters und trennte dessen Ohr (Ohrläppchen?) ab.',
        48: 'Und Jesus antwortete {und sagte zu} ihnen: „Wie gegen einen Räuber (Rebellen, Aufwiegler) seid ihr mit Schwertern und Keulen ausgezogen, um mich festzunehmen!?',
        49: 'Tag für Tag (Tagsüber) war ich bei euch im Tempel und lehrte (Tag für Tag lehrte ich bei euch im Tempel) und ihr habt mich nicht ergriffen. Aber [es sei], dass die Schriften erfüllt werden! (Aber [all dies geschieht], damit die Schriften erfüllt werden.) “',
        50: 'Und indem sie ihn verließen, flohen alle.',
        51: 'Und ein gewisser junger Mann folgte ihm (wollte ihm folgen), bekleidet mit einem Leinentuch über [seinem] nackten [Körper], und sie ergreifen (ergriffen) ihn,',
        52: 'aber er ließ das Leinentuch zurück und floh nackt.',
        53: 'Und sie führten Jesus zum Hohepriester ab und alle obersten (führenden, Hohe-) Priester und die Ältesten und die Schriftgelehrten kommen (kamen) zusammen (versammelten sich).',
        54: 'Und Petrus war ihm in einiger Entfernung bis nach drinnen (hinein) in den Innenhof (Palast) des Hohepriesters gefolgt, und [dort] saß er (setzte er sich) bei den Dienern (Wächtern) und wärmte sich am Licht (Feuer).',
        55: 'Die obersten (führenden, Hohen) Priester {aber} und der ganze Hohe Rat (Sanhedrin) suchten nach einer Zeugenaussage gegen Jesus, um ihn zu töten, aber sie fanden keine,',
        56: 'denn viele machten Falschaussagen gegen ihn, aber ihre Aussagen waren nicht übereinstimmend (gleich).',
        57: 'Und einige standen auf und machten gegen ihn Falschaussagen, {sagend}:',
        58: '„Wir haben gehört, wie (dass) er sagte: Ich werde diesen von Hand erbauten Tempel abreißen und innerhalb von drei Tagen einen anderen, nicht von Hand erbauten, errichten!“',
        59: 'Aber (und) nicht einmal (auch nicht) darin (so) war ihre Aussage (ihr Zeugnis) übereinstimmend (gleich).',
        60: 'Da (und) stand der Hohe Priester auf, [trat] in die Mitte und fragte (befragte, verhörte) Jesus, {indem er sagte}: „Entgegnest (antwortest) du gar nichts [auf das], was diese gegen dich als Aussage machen?“(„Entgegnest du nichts? Was sagen diese gegen dich aus?“)',
        61: 'Er aber schwieg [weiter] und antwortete gar nichts. Wieder fragte (befragte, verhörte) ihn der Hohepriester und sagt [e] [zu] ihm: „Bist du der Messias (Gesalbte, Christus, versprochene Retter), der Sohn des Gepriesenen (Hochgelobten, zu Preisenden)?“',
        62: 'Da (aber) sagte Jesus: „Ich bin [es], und ihr werdet den Menschensohn (Sohn des Menschen) sehen, wie er an der rechten [Seite] des Allmächtigen (der Macht) sitzt und mit den Wolken des Himmels kommt.“',
        63: 'Da (aber) zerriss der Hohe Priester seine Kleider [und] sagt [e]: „Wozu (was) bedürfen wir noch Zeugen?',
        64: 'Ihr habt die Gotteslästerung gehört. Was ist eurer Urteil (eure Meinung)?“Und (aber) sie alle verurteilten ihn, des Todes schuldig zu sein.',
        65: 'Dann spuckten ihn einige an und verhüllten sein Gesicht und prügelten ihn und sagten ihm: „Prophezeie!“, und [auch] die Diener nahmen sich seiner mit Ohrfeigen an.',
        66: 'Und während Petrus unten im Hof war, kommt (kam) eine der Mägde des Hohepriesters,',
        67: 'und als sie sah, dass Petrus sich wärmte, blickte sie ihn an und sagt [e]: „Auch du warst mit dem Nazarener Jesus!“',
        68: 'Aber er leugnete und sagte: „Weder weiß ich noch verstehe ich, was du sagst.“Und er ging hinaus nach draußen in den Vorhof, {und ein Hahn krähte}.',
        69: 'Und als die Magd ihn sah, sagte sie erneut zu den Dabeistehenden: „Dieser gehört zu ihnen!“',
        70: 'Aber er leugnete wieder. Und kurz danach sagten diejenigen, die dabeistanden, erneut zu Petrus: „Wahrhaftig, du gehörst zu ihnen, denn du bist auch ein Galiläer!“',
        71: 'Er aber verfluchte und zu schwor: „Ich kenne diesen Menschen nicht, [von] den ihr sprecht!“',
        72: 'Und sogleich krähte zum zweiten Mal ({zum zweiten Mal}) ein Hahn. Da erinnerte sich Petrus an das Wort, wie Jesus zu ihm gesagt hatte: „Bevor dem zweimaligen Krähen des Hahns wirst du mich dreimal verleugnen.“Und er brach in Tränen aus.',
    },
    15: {
        1: 'Und dann frühmorgens, nachdem die Oberpriester mit den Ältesten und Schriftgelehrten und dem gesamten Synedrium Rat gehalten hatten (einen Plan gefasst hatten) [und] nachdem sie Jesus gefesselt hatten, führten sie ihn ab und lieferten ihn an Pilatus aus.',
        2: "Und Pilatus fragte ihn: „Bist ''du'' der König der Juden (Judäer)?“Er {aber} antwortete ihm {und sagt}: „Du sagst [es].“",
        3: '{Und} [da] klagten ihn die Oberpriester vieler [Dinge] an.',
        4: 'Und Pilatus fragte ihn erneut {und sagte}: „Antwortest du nichts? Siehe, wie viel sie dich beschuldigen!“',
        5: 'Jesus aber antwortete nicht länger, sodass Pilatus sich wunderte.',
        6: "Nun ließ er ihnen zum Fest ''einen'' Gefangenen frei, den sie erbaten.",
        7: 'Es war aber einer, der Barabbas genannt wurde [und] mit den Aufständischen gefangen, worden war, welche während des Aufstandes einen Mord begangen hatten.',
        8: 'Und die Menschenmenge stieg hinauf und begann zu bitten, [zu tun] was er für sie zu tun pflegte.',
        9: 'Und Pilatus antwortete ihnen {und sagte}: „Wollt ihr, dass ich euch den »König der Juden (Judäer) « freilasse?“',
        10: 'Denn er wusste, dass die Oberpriester ihn aus Neid übergeben hatten.',
        11: 'Die Oberpriester aber hetzten die Menschenmenge auf, dass er ihnen vielmehr Barabbas freilassen solle.',
        12: 'Und Pilatus antwortete ihnen erneut [und sagte]: „Was nun wollt ihr, dass ich [mit dem] mache, den ihr den »König der Juden (Judäer) « nennt?“',
        13: 'Sie aber schrien erneut: „Kreuzige ihn!“',
        14: 'Und Pilatus sagte zu ihnen: „Was hat er denn Schlechtes getan?“Sie aber schrien maßlos: „Kreuzige ihn!“',
        15: 'Da aber Pilatus der Menschenmenge gefallen wollte, ließ er ihnen Barabbas frei, und übergab Jesus, nachdem er ihn gegeißelt hatte, damit er gekreuzigt werde.',
        16: 'Und die Soldaten führten ihn in den Hof – das heißt: das Prätorium – und {sie} riefen die gesamte Truppe zusammen.',
        17: 'Und sie ziehen ihm einen Purpurmantel an, und sie flochten eine Krone aus Dornen und setzen sie ihm auf.',
        18: 'Und sie begannen, ihn zu grüßen: „Sei gegrüßt, König der Juden (Judäer)!“',
        19: 'Und sie schlugen seinen Kopf mit einem Rohr und bespuckten ihn, und sie gingen auf die Knie und beteten ihn an.',
        20: 'Und als sie ihn verspottet hatten, zogen sie ihm den Purpurmantel aus, und sie zogen ihm seine Kleider an. Dann führen sie ihn ab, um ihn zu kreuzigen.',
        21: 'Und sie zwangen einen Passanten, einen gewissen Simon Kyrene, der vom Feld kam, von Vater von Alexander und Rufus, damit er sein (dessen) Kreuz träge.',
        22: 'Und sie bringen ihn zu dem Ort Golgata – das heißt übersetzt: Ort des Schädels.',
        23: 'Und sie gaben ihm mit Myrrhe vermischten Wein, er aber nahm [den Wein] nicht.',
        24: "Und sie kreuzigen ihn und '' {sie} teilten seine Kleider, indem sie ein Los über {sie} [die Kleider] warfen'', wer was nähme.",
        25: 'Und es war die dritte Stunde, als sie ihn kreuzigten.',
        26: 'Und als Inschrift seiner Schuld stand über [ihm] geschrieben: Der König der Juden (Judäer).',
        27: 'Und zusammen mit ihm kreuzigen sie zwei Räuber, einen zur seiner Rechten und einen zur seiner Linken.',
        28: '{Und erfüllt wurde die Schrift[, die sagt]: Mit den Ungerechten wurde er [zusammengetan] {angerechnet}}',
        29: 'Und die Vobeilaufenden lästerten {über} ihn, schüttelten ihre Köpfe und sagten: „Aha! Der [du] den Tempel niederreißt und in drei Tagen aufbaust,',
        30: 'rette dich selbst, [indem du] von dem Kreuz herabsteigst!“',
        31: 'Genauso spotteten auch die Oberpriester zueinander mit den Schriftgelehrten { und sagten}: „Andere hat er gerettet, sich selbst vermag er nicht zu retten.',
        32: 'Der Gesalbte (Christus), der König Israels, er soll jetzt von dem Kreuz herabsteigen, damit wir sehen und glauben!“Und die Mitgekreuzigten {mit ihm} beleidigten ihn [auch].',
        33: 'Und zur sechsten Stunde, geschah eine Finsternis über dem ganzen Land bis zur neunten Stunde.',
        34: 'Und zur neunten Stunde rief Jesus mit lauter Stimme: „Eloi, eloi, lema sabachthani?“Das heißt übersetzt: „Mein Gott, mein Gott, warum hast du mich verlassen?“',
        35: 'Und als einige der Beistehenden [dies] hörten, sprachen sie: „Siehe, er ruft Elia.“',
        36: 'Jemand aber lief [und] füllte einen Schwamm [mit] Essig und steckte [ihn] auf ein Rohr, gab ihm zu trinken und sprach: „Halt, lasst uns sehen, ob Elia kommt, um ihn herabzunehmen!“',
        37: 'Jesus aber stieß einen lauten Schrei aus und tat seinen letzten Atem.',
        38: 'Und der Vorhang des Tempels wurde entzwei zerrissen von oben nach unten.',
        39: 'Als nun der Centurio, der ihm gegenüber dabeistand, sah, dass er auf diese Weise schrie [und] seinen letzten Atem tat, sagte er: „Wahrlich, dieser Mensch war [und bleibt] Gottes Sohn!“',
        40: 'Es waren aber auch Frauen [anwesend], die von Weitem zuschauten, unter ihnen auch Maria Magdalena und Maria, die Mutter von Jakobus dem Jüngeren (Kleineren) und Joses, und Salome,',
        41: '{und} die ihm, als er in Galiläa war, nachgefolgt waren und ihm gedient hatten und viele andere [Frauen], die mit ihm nach Jerusalem hinaufgestiegen waren.',
        42: 'Und als es Abend wurde, weil es der Tag der Vorbereitung war, das heißt: der Tag vor dem Sabbat,',
        43: 'kam Josef von Arimatäa, ein angesehenes Mitglied des Rates, der auch selbst das Reich Gottes angenommen hatte, wagte [es] und ging hinein zu Pilatus, und {er} bat um den Leichnam (Leib) von Jesus.',
        44: 'Pilatus aber wunderte sich, dass er schon gestorben sei, und er rief den Centurion herbei und fragte ihn, ob er lange gestorben sei.',
        45: 'Und als er [es] von dem Centurion erfuhr, gab er Josef den Leichnam.',
        46: 'Und er kaufte ein Leinentuch und nahm ihn herab, wickelte [ihn] in das Leinentuch, und {er} legte ihn in ein Grab, das in einen Felsen gehauen war, und er rollte einen Stein vor den Eingang (Tür) des Grabes.',
        47: 'Aber Maria Magdalena und Maria, die [Mutter] von Joses, sahen, wo er hingelegt worden war.',
    },
    16: {
        1: 'Und als der Sabbat vorüber war, kauften Maria [von, aus] Magdala und Maria, [die Mutter] des Jakobus und Salome Spezereien (wohlriechende Kräuter, Gewürze), um [zum Grab] zu gehen [und] ihn zu salben.',
        2: 'Und sehr (ganz) früh am ersten [Tag] der Woche (am Sonntag) gingen sie zum Grab, während (als) die Sonne aufging.',
        3: 'Und sie sprachen zu einander: Wer wälzt {für} uns den Stein aus der Tür des Grabes (von der Tür des Grabes ab)?',
        4: 'Und als sie aufblickten, nehmen sie wahr (merken sie), dass der Stein abgewälzt (weggewälzt) war; er war nämlich sehr groß.',
        5: 'Und nachdem sie hineingegangen waren in das Grab, sahen sie einen Jüngling zur Rechten (auf der rechten Seite) sitzen, der ein weißes Gewand an (gezogen) hatte, und sie entsetzten sich (waren sehr erstaunt).',
        6: 'Er aber spricht zu ihnen: Entsetzt euch nicht (Seid nicht erstaunt)! Ihr sucht Jesus, den Nazarener, den Gekreuzigten. Er ist auferstanden (er wurde auferweckt), er ist nicht hier. Hier [ist] (Siehe) der Ort (die Stelle), wo sie ihn hingelegt haben.',
        7: 'Aber los! (Auf!, Geht fort, Doch geht), sagt [es] seinen Jüngern und Petrus, dass er euch vorangeht nach Galiläa. Dort werdet ihr ihn sehen, wie er euch sagte.',
        8: 'Und sie gingen hinaus und flohen von dem Grab, sie waren nämlich ergriffen von (hatten) Angst (Zittern) und Entsetzen (Bestürzung). Und sie sagten keinem (niemandem) etwas; denn sie fürchteten sich.',
        9: 'Nachdem (als, weil) er auferstanden war am frühen Morgen (im Morgengrauen) des ersten Tags der Woche (des Sabbats), erschien er als erstes Maria Magdalena, von der er sieben Dämonen ausgetrieben hatte.',
        10: 'Als sie ging, es denen zu bekanntzumachen (zu verkündigen), die bei ihm gewesen waren, trauerten sie weinten sie.',
        11: 'Und eben diese – obwohl (als, nachdem) sie hörten, dass [Jesus] lebte und von ihr gesehen worden war, da glaubten sie [es ihr] nicht.',
        12: 'Danach {aber} erschien er zwei von ihnen, als (während) sie unterwegs waren, in anderer Gestalt, als (während) sie aufs Land [hinaus] gingen.',
        13: 'Auch diese gingen und berichteten es den anderen. Die glaubten es jenen [ebenfalls] nicht.',
        14: 'Später wiederum (aber), als sie gerade [zu Tische] lagen (gemeinsam aßen) erschien er den elf [Jüngern], und er tadelte ihren Unglauben (ihr Mißtrauen, ihre Treulosigkeit) und ihre Hartherzigkeit, dass sie denen, die ihn auferstanden gesehen hatten, nicht geglaubt (vertraut) hatten.',
        15: 'Und er sagte zu ihnen: „Geht in die ganze Welt hinaus und macht meine Freuden-Botschaft bekannt (verkündet mein Evangelium) der ganzen Schöpfung.',
        16: 'Wer glaubt (vertraut, treu ist) und sich taufen lässt, wird gerettet werden. Wer dagegen nicht glaubt (nicht vertraut, treulos ist), wird gerichtet werden.',
        17: 'Diese Wunder (Zeichen) {aber} werden die Glaubenden begleiten: In meinem Namen werden sie Dämonen (Geister, übernatürliche Wesen) austreiben; in neuen (d.h. unbekannten) Sprachen (Zungen) werden sie reden;',
        18: 'sie werden Schlangen aufheben; und wenn sie etwas Tödliches tranken, werden sie keinesfalls sterben; bei Kranken werden sie Hände auflegen und es wird {ihnen} [diesen wieder] gut gehen.“',
        19: 'Der Herr, Jesus, wurde {nun zwar} nach diesem Reden in den Himmel aufgenommen und setzte sich zu Gottes rechter Seite,',
        20: 'jene aber gingen hinaus [in die Welt] und verkündeten (predigten) überall, wobei der Herr mitwirkte und [ihre] Rede (das Wort) dadurch bekräftigte, dass sich Wunder einstellten (durch nachfolgende Zeichen stärkte/bestätigte).',
    },
}
